// MBG Kitchen — Frontend SPA (vanilla JS)
const fmtIDR = (n) => 'Rp ' + Number(n || 0).toLocaleString('id-ID');
const fmtNum = (n) => Number(n || 0).toLocaleString('id-ID');
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }) : '-';
const getInitials = (name) => (name || '').split(' ').map(w => w[0]).filter(Boolean).slice(0, 2).join('').toUpperCase() || '?';


const api = {
  async get(path) {
    const r = await fetch('/api' + path, { credentials: 'include' });
    if (!r.ok) {
      let msg = r.status + ' ' + r.statusText;
      try { const e = await r.json(); msg = e.error || msg; } catch {}
      throw new Error(msg);
    }
    return r.json();
  },
  async post(path, body) {
    const r = await fetch('/api' + path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), credentials: 'include' });
    if (!r.ok) {
      let msg = r.status + ' ' + r.statusText;
      try { const e = await r.json(); msg = e.error || msg; } catch {}
      throw new Error(msg);
    }
    return r.json();
  },
  async put(path, body) {
    const r = await fetch('/api' + path, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body), credentials: 'include' });
    if (!r.ok) {
      let msg = r.status + ' ' + r.statusText;
      try { const e = await r.json(); msg = e.error || msg; } catch {}
      throw new Error(msg);
    }
    return r.json();
  },
  async del(path) {
    const r = await fetch('/api' + path, { method: 'DELETE', credentials: 'include' });
    if (!r.ok) {
      let msg = r.status + ' ' + r.statusText;
      try { const e = await r.json(); msg = e.error || msg; } catch {}
      throw new Error(msg);
    }
    return r;
  },
};

// Editor
function toggleSidebarCollapse() {
  const sb = document.getElementById('sidebar');
  const app = document.getElementById('app');
  const isCollapsed = sb.classList.toggle('collapsed');
  app.classList.toggle('sidebar-collapsed', isCollapsed);
  localStorage.setItem('sidebar_collapsed', isCollapsed ? '1' : '');
}
function expandSidebar() {
  const sb = document.getElementById('sidebar');
  const app = document.getElementById('app');
  sb.classList.remove('collapsed');
  app.classList.remove('sidebar-collapsed');
  localStorage.setItem('sidebar_collapsed', '');
}
function toggleDarkMode() {
  const html = document.documentElement;
  const isDark = html.classList.toggle('dark');
  localStorage.setItem('dark_mode', isDark ? '1' : '');
  document.querySelectorAll('#sun-icon,.sun-icon-mobile').forEach(e => e.classList.toggle('hidden', !isDark));
  document.querySelectorAll('#moon-icon,.moon-icon-mobile').forEach(e => e.classList.toggle('hidden', isDark));
}
function initDarkMode() {
  if (localStorage.getItem('dark_mode')) {
    document.documentElement.classList.add('dark');
    document.querySelectorAll('#sun-icon,.sun-icon-mobile').forEach(e => e.classList.remove('hidden'));
    document.querySelectorAll('#moon-icon,.moon-icon-mobile').forEach(e => e.classList.add('hidden'));
  }
}
function initSidebar() {
  const sb = document.getElementById('sidebar');
  const app = document.getElementById('app');
  if (localStorage.getItem('sidebar_collapsed')) {
    sb.classList.add('collapsed');
    app.classList.add('sidebar-collapsed');
  }
}

function toggleSidebar() {
  const sb = document.getElementById('sidebar');
  const ov = document.getElementById('sidebar-overlay');
  const open = sb.classList.contains('translate-x-0');
  if (open) {
    sb.classList.remove('translate-x-0');
    sb.classList.add('-translate-x-full');
    ov.classList.add('hidden');
  } else {
    sb.classList.remove('-translate-x-full');
    sb.classList.add('translate-x-0');
    ov.classList.remove('hidden');
  }
}
function closeSidebar() {
  const sb = document.getElementById('sidebar');
  const ov = document.getElementById('sidebar-overlay');
  sb.classList.remove('translate-x-0');
  sb.classList.add('-translate-x-full');
  ov.classList.add('hidden');
}

function showAccessDenied(msg) {
  const c = document.getElementById('content');
  c.innerHTML = `<div class="flex flex-col items-center justify-center py-24 text-stone-400">
    <svg class="w-20 h-20 mb-6 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24" stroke-width="1.5">
      <rect x="3" y="11" width="18" height="11" rx="2" ry="2"/>
      <path d="M7 11V7a5 5 0 0110 0v4"/>
      <circle cx="12" cy="16" r="1.5"/>
      <line x1="12" y1="16" x2="12" y2="13"/>
    </svg>
    <div class="text-lg font-semibold text-stone-500 mb-1">Akses Ditolak</div>
    <p class="text-sm text-center max-w-xs">${msg || 'Anda tidak memiliki izin untuk mengakses halaman ini.'}</p>
  </div>`;
}
// ===== Modules definition =====

// ===== Generic CRUD =====
let _crudCfg = null;
let _crudState = { page: 1, limit: 25, search: '', total: 0, totalPages: 1 };

async function renderCrud(cfg) {
  _crudCfg = cfg;
  _crudState = { page: 1, limit: 25, search: '', total: 0, totalPages: 1 };
  const c = document.getElementById('content');
  c.innerHTML = `<div id="crud-stats" class="${cfg.stats ? '' : 'hidden'}">
    <div id="crud-stats-content" class="flex flex-wrap gap-3 mb-4"></div>
  </div>
  <div class="flex flex-wrap items-center justify-between gap-3 mb-4">
    <div class="flex items-center gap-2">
      <button id="add-btn" class="h-11 px-5 bg-[#1e40af] hover:bg-[#1d4ed8] text-white rounded-xl text-sm font-semibold shadow-sm transition-all flex items-center gap-2">
        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
        Tambah
      </button>
      <button id="crud-delete-selected" onclick="deleteSelectedCrud()" class="hidden h-10 px-4 text-sm font-medium text-red-600 bg-red-50 hover:bg-red-100 rounded-xl items-center gap-1.5 shadow-sm transition-all">
        Hapus Terpilih <span id="crud-selected-count" class="font-bold">0</span>
      </button>
      ${cfg.helpContent ? `<button onclick="showCrudInfo()" class="w-9 h-9 flex items-center justify-center rounded-xl border border-stone-200 bg-white text-stone-400 hover:text-stone-600 hover:bg-stone-50 shadow-sm transition-all" title="Info halaman ini">
        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>
      </button>` : ''}
    </div>
    <div class="flex items-center gap-2">
      <div class="relative">
        <input id="crud-search" placeholder="Cari..." class="w-56 h-11 pl-10 pr-4 rounded-xl border border-stone-200 bg-white text-sm shadow-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all">
        <svg class="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"/></svg>
      </div>
      ${cfg.sync ? `<button id="sync-btn" onclick="syncCrudData()" class="h-11 px-4 border border-emerald-300 text-emerald-700 hover:bg-emerald-50 rounded-xl text-sm font-medium shadow-sm transition-all">${cfg.sync.label}</button>` : ''}
      ${cfg.extraButtons ? cfg.extraButtons.map(b => `<button onclick="${b.onclick}" class="h-11 px-4 border border-stone-200 text-stone-700 hover:bg-stone-50 rounded-xl text-sm font-medium shadow-sm transition-all">${b.label}</button>`).join('') : ''}
      <button onclick="exportXlsx()" class="h-11 px-4 border border-stone-200 text-stone-700 hover:bg-stone-50 rounded-xl text-sm font-medium shadow-sm transition-all">Export XLSX</button>
    </div>
  </div>
  <div id="table-wrap" class="bg-white rounded-2xl border border-stone-200 shadow-sm overflow-hidden"></div>
  <div id="crud-pagination" class="flex items-center justify-between mt-3"></div>`;
  window._crudInfoCfg = cfg;
  document.getElementById('add-btn').onclick = () => openForm(cfg, null);

  const searchInput = document.getElementById('crud-search');
  let debounceTimer;
  searchInput.oninput = function() {
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(() => {
      _crudState.search = this.value;
      _crudState.page = 1;
      reloadCrud(cfg);
    }, 300);
  };

  await reloadCrud(cfg);
}

async function reloadCrud(cfg) {
  const params = new URLSearchParams({ page: _crudState.page, limit: _crudState.limit, search: _crudState.search });
  const res = await api.get(cfg.endpoint + '?' + params);
  const rows = Array.isArray(res.data) ? res.data : (Array.isArray(res) ? res : []);
  const pagination = res.pagination || { total: rows.length, totalPages: 1, page: 1 };
  _crudState = { ..._crudState, total: pagination.total, totalPages: pagination.totalPages, page: pagination.page };
  window._crudRows = rows;

  // Load stats jika dikonfigurasi
  if (cfg.stats) {
    (async () => {
      try {
        const statsRes = await api.get(cfg.stats.endpoint);
        const totalVal = Number(statsRes.total) || 0;
        const contentEl = document.getElementById('crud-stats-content');
        if (contentEl) {
          var cards = '';
          var fmt = cfg.stats.format === 'num' ? fmtNum(totalVal) : totalVal;
          cards += '<div class="flex-1 min-w-[140px] bg-gradient-to-br from-blue-50 to-blue-100/60 rounded-2xl border border-blue-200/60 px-4 py-3 shadow-sm"><div class="text-[10px] font-semibold uppercase tracking-wider text-blue-700 mb-0.5">' + cfg.stats.label + '</div><div class="text-xl font-bold text-blue-800">' + fmt + '</div></div>';
          if (cfg.stats.extra) {
            cfg.stats.extra.forEach(function(x) {
              var c = x.color || 'blue';
              // Gunakan nilai total dari backend (prefixed total_) agar akurat untuk seluruh data
              var val = statsRes['total_' + x.field] != null ? Number(statsRes['total_' + x.field]) : 0;
              cards += '<div class="flex-1 min-w-[140px] bg-gradient-to-br from-' + c + '-50 to-' + c + '-100/60 rounded-2xl border border-' + c + '-200/60 px-4 py-3 shadow-sm"><div class="text-[10px] font-semibold uppercase tracking-wider text-' + c + '-700 mb-0.5">' + x.label + '</div><div class="text-xl font-bold text-' + c + '-800">' + fmtNum(val) + '</div></div>';
            });
          }
          contentEl.innerHTML = cards;
        }
      } catch (e) {
        console.warn('Gagal load stats:', e.message);
      }
    })();
  }

  const w = document.getElementById('table-wrap');
  if (!rows.length) {
    w.innerHTML = '<div class="py-16 text-center text-stone-400"><svg class="w-12 h-12 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="2" y="3" width="20" height="18" rx="2" ry="2"/><path d="M12 17v-6"/><circle cx="12" cy="21" r="2"/></svg><div class="text-sm">Belum ada data</div><div class="text-xs text-stone-400 mt-1">Klik "Tambah" untuk mulai.</div></div>';
    document.getElementById('crud-pagination').innerHTML = '';
    return;
  }

  const headers = cfg.cols.map(k => `<th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">${cfg.fields.find(f => f.k === k)?.l || k}</th>`).join('');
  const body = rows.map(r => `<tr class="border-b border-stone-50 hover:bg-stone-50/50 transition-colors">
    <td class="px-4 py-3">
      <input type="checkbox" value="${r.id}" onchange="updateSelectedCrudCount()" class="crud-checkbox cb-modern">
    </td>
    ${cfg.cols.map(k => {
      const f = cfg.fields.find(x => x.k === k);
      const v = r[k];
      let cell = v == null || v === '' ? '-' : v;
      if (f?.fmt === 'idr') cell = `<span class="mono">${fmtIDR(v)}</span>`;
      else if (f?.fmt === 'num') cell = `<span class="mono">${f.decimals != null ? Number(v).toFixed(f.decimals) : fmtNum(v)}</span>`;
      else if (f?.fmt === 'pct') cell = `<span class="mono">${Math.round(v * 100)}</span>%`;
      else if (f?.type === 'date') cell = fmtDate(v);
      return `<td class="px-4 py-3 text-xs text-stone-600">${cell}</td>`;
    }).join('')}
    <td class="px-4 py-3 text-right whitespace-nowrap">
      ${cfg.suratJalan ? '<button onclick="cetakSuratJalan(' + r.id + ')" class="w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-emerald-600 hover:bg-emerald-50 transition-all" title="Cetak Surat Jalan"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="6 9 6 2 18 2 18 9"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8"/></svg></button>' : ''}
      <button onclick='editRow(${JSON.stringify(cfg).replace(/'/g, "&#39;")}, ${JSON.stringify(r).replace(/'/g, "&#39;")})' class="w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-blue-600 hover:bg-blue-50 transition-all" title="Edit"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
      <button onclick='deleteRow("${cfg.endpoint}", ${r.id}, ${JSON.stringify(cfg).replace(/'/g, "&#39;")})' class="w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-red-600 hover:bg-red-50 transition-all" title="Hapus"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>
    </td></tr>`).join('');
  w.innerHTML = `<div class="overflow-x-auto"><table class="w-full"><thead><tr class="border-b border-stone-100">
    <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500 w-10">
      <input type="checkbox" id="crud-select-all" onchange="toggleSelectAllCrud(this)" class="cb-modern">
    </th>
    ${headers}<th class="px-4 py-3.5 text-right text-[10px] font-bold uppercase tracking-wider text-stone-500">Aksi</th></tr></thead><tbody>${body}</tbody></table></div>`;

  renderCrudPagination();
}

function renderCrudPagination() {
  const wrap = document.getElementById('crud-pagination');
  const { page, totalPages, total } = _crudState;
  if (totalPages <= 1) { wrap.innerHTML = total > 0 ? `<span class="text-sm text-stone-400">${total} data</span>` : ''; return; }
  const prev = page > 1 ? `<button onclick="crudGoToPage(${page - 1})" class="px-3 py-1.5 text-sm font-medium rounded-lg border border-stone-200 hover:bg-stone-50 hover:border-stone-300 transition-all">Prev</button>` : '';
  const next = page < totalPages ? `<button onclick="crudGoToPage(${page + 1})" class="px-3 py-1.5 text-sm font-medium rounded-lg border border-stone-200 hover:bg-stone-50 hover:border-stone-300 transition-all">Next</button>` : '';
  wrap.innerHTML = `<span class="text-sm text-stone-500">${total} data — Hal ${page} dari ${totalPages}</span><div class="flex gap-2">${prev}${next}</div>`;
}

function crudGoToPage(p) {
  _crudState.page = p;
  reloadCrud(_crudCfg);
}

function editRow(cfg, row) { openForm(cfg, row); }
async function deleteRow(endpoint, id, cfg) {
  if (!await showConfirm('Hapus data ini?')) return;
  await api.del(endpoint + '/' + id); reloadCrud(cfg);
}

function toggleSelectAllCrud(master) {
  document.querySelectorAll('.crud-checkbox').forEach(cb => cb.checked = master.checked);
  updateSelectedCrudCount();
}
function updateSelectedCrudCount() {
  var checked = document.querySelectorAll('.crud-checkbox:checked').length;
  var btn = document.getElementById('crud-delete-selected');
  var countEl = document.getElementById('crud-selected-count');
  if (!btn || !countEl) return;
  if (checked > 0) {
    btn.classList.remove('hidden');
    btn.classList.add('inline-flex');
    countEl.textContent = checked;
  } else {
    btn.classList.add('hidden');
    btn.classList.remove('inline-flex');
  }
}
async function deleteSelectedCrud() {
  var cfg = _crudCfg;
  if (!cfg) return;
  var checked = document.querySelectorAll('.crud-checkbox:checked');
  var ids = Array.from(checked).map(cb => parseInt(cb.value)).filter(id => !isNaN(id));
  if (!ids.length) return showAlert('Pilih data yang akan dihapus', 'warning');
  if (!await showConfirm('Hapus ' + ids.length + ' data terpilih?')) return;
  try {
    await api.post(cfg.endpoint + '/bulk-delete', { ids });
    showToast(ids.length + ' data berhasil dihapus', 'success');
    reloadCrud(cfg);
  } catch (e) {
    showToast('Gagal menghapus: ' + (e.message || 'Unknown error'), 'error');
  }
}

async function syncCrudData() {
  const cfg = _crudCfg;
  if (!cfg || !cfg.sync) return;
  if (!await showConfirm(cfg.sync.confirm || 'Sync data ini?', 'Ya, Sync')) return;
  try {
    const res = await api.post(cfg.sync.endpoint, {});
    showToast(`${res.updated || res.recalculated} data diperbarui dari ${res.total}`, 'success');
    reloadCrud(cfg);
  } catch (e) {
    showAlert(e.message || 'Gagal sync', 'error');
  }
}

function exportXlsx() {
  const cfg = _crudCfg;
  if (!cfg) return;
  const rows = window._crudRows || [];
  if (!rows.length) { showAlert('Tidak ada data untuk diexport', 'warning'); return; }
  const headers = cfg.cols.map(k => cfg.fields.find(f => f.k === k)?.l || k);
  const data = rows.map(r => cfg.cols.map(k => r[k] == null ? '' : r[k]));
  data.unshift(headers);
  const ws = XLSX.utils.aoa_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Data');
  XLSX.writeFile(wb, (cfg.title || cfg.endpoint) + '.xlsx');
}

async function exportBahanBakuXlsx() {
  const cfg = getBahanCrud();
  const rows = await api.get('/bahan_baku');
  if (!rows.length) { showAlert('Tidak ada data untuk diexport', 'warning'); return; }
  const headers = cfg.cols.map(k => cfg.fields.find(f => f.k === k)?.l || k);
  const data = rows.map(r => cfg.cols.map(k => r[k] == null ? '' : r[k]));
  data.unshift(headers);
  const ws = XLSX.utils.aoa_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, 'Bahan Baku');
  XLSX.writeFile(wb, 'bahan_baku.xlsx');
}

function renderField(f, editing) {
  if (f.type === 'hidden') {
    return `<input type="hidden" id="f-${f.k}" value="${editing?.[f.k] || ''}" />`;
  }
  const ro = f.readOnly;
  const roCls = ro ? 'bg-stone-100 text-stone-500 cursor-not-allowed' : '';
  const val = editing?.[f.k];
  let actionHtml = '';
  if (f.action) {
      actionHtml = `<button type="button" onclick='${f.action.onclick}' class="text-[10px] border border-blue-300 text-blue-700 hover:bg-blue-50 px-2 py-1 rounded-lg flex items-center gap-1 font-semibold"><svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>${f.action.label}</button>`;
  }
  let input;
  if (f.type === 'select') {
    input = `<select id="f-${f.k}" ${ro ? 'disabled' : ''} class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all ${roCls}">
      <option value="">— Pilih —</option>${f.opts.map(o => `<option value="${o}" ${val === o ? 'selected' : ''}>${o}</option>`).join('')}
    </select>`;
  } else if (f.type === 'select-api') {
    input = `<select id="f-${f.k}" ${ro ? 'disabled' : ''} class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all ${roCls}"><option value="">— Memuat data... —</option></select>`;
  } else if (f.type === 'textarea') {
    input = `<textarea id="f-${f.k}" rows="2" ${ro ? 'readonly' : ''} class="mt-1.5 w-full px-3 py-2.5 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all ${roCls}">${val || ''}</textarea>`;
  } else {
    const itype = f.type === 'number' ? 'number' : f.type === 'date' ? 'date' : 'text';
    let ival = val != null ? (f.type === 'date' ? String(val).slice(0,10) : val) : '';
    if (f.fmt === 'pct' && val != null) ival = Math.round(val * 100);
    if (f.fmt === 'num' && f.decimals != null && val != null) ival = Number(val).toFixed(f.decimals);
    input = `<input id="f-${f.k}" type="${itype}" value="${ival}" ${ro ? 'readonly' : ''} class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all ${f.type === 'number' ? 'mono' : ''} ${roCls}" />`;
  }
  const label = `<label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">${f.l}${f.req ? ' <span class="text-red-500">*</span>' : ''}</label>`;
  const header = f.action ? `<div class="flex items-center justify-between">${label}${actionHtml}</div>` : label;
  const info = f.info ? `<div class="text-[10px] text-stone-400 mt-1 leading-relaxed">${f.info}</div>` : '';
  return `<div class="${f.type === 'hidden' ? '' : 'mb-4'}">${header}${input}${info}</div>`;
}

function openForm(cfg, editing) {
  const title = (editing ? 'Edit ' : 'Tambah ') + MODULES[(location.pathname || '/dashboard').slice(1)].title;
  document.getElementById('modal-title').textContent = title;
  const body = document.getElementById('modal-body');

  const apiSelects = cfg.fields.filter(f => f.type === 'select-api');

  var formHelp = cfg.formHelp ? '<div class="flex items-start gap-2.5 p-3 mb-4 bg-sky-50 border border-sky-200 rounded-xl text-xs text-sky-800 leading-relaxed"><svg class="w-4 h-4 mt-0.5 shrink-0 text-sky-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg><div>' + cfg.formHelp + '</div></div>' : '';

  if (cfg.groups && Array.isArray(cfg.groups)) {
    let html = formHelp;
    cfg.groups.forEach(g => {
      const gFields = cfg.fields.filter(f => f.group === g.key && f.type !== 'hidden');
      if (!gFields.length) return;
      html += `<div class="mb-5">
        <h4 class="text-xs font-bold uppercase tracking-wider text-stone-500 mb-3 pb-2 border-b border-stone-200">${g.label}</h4>
        <div class="grid grid-cols-1 ${g.cols === 2 ? 'md:grid-cols-2' : ''} gap-x-4 gap-y-1">`;
      gFields.forEach(f => { html += renderField(f, editing); });
      html += `</div></div>`;
    });
    cfg.fields.filter(f => f.type === 'hidden').forEach(f => { html += renderField(f, editing); });
    body.innerHTML = html;
  } else {
    body.innerHTML = formHelp + cfg.fields.map(f => renderField(f, editing)).join('');
  }

  // AI button for nutrition fields (sp-referensi) — disabled temporarily
  // var aiFields = cfg.fields.filter(function(f) { return f.ai; });
  // if (aiFields.length) {
  //   var aiBtn = document.createElement('div');
  //   aiBtn.className = 'flex items-center justify-between pt-2';
  //   aiBtn.innerHTML = '<div class="text-xs text-stone-400">Isi gizi dengan AI berdasarkan nama bahan</div>' +
  //     '<button type="button" onclick="fillAiNutrisiSp()" class="px-4 py-2 text-xs font-medium text-orange-700 bg-orange-50 border border-orange-200 rounded-lg hover:bg-orange-100">Isi AI</button>';
  //   body.appendChild(aiBtn);
  //   window._aiFields = aiFields;
  // }

  apiSelects.forEach(f => {
    const sel = document.getElementById('f-' + f.k);
    api.get(f.source).then(rows => {
      const list = Array.isArray(rows) ? rows : (rows.data || []);
      sel.innerHTML = '';
      if (!list.length) {
        sel.innerHTML = '<option value="">— Data ' + f.l + ' belum tersedia —</option>';
        var emptyInfo = document.createElement('div');
        emptyInfo.className = 'flex items-center gap-2 p-3 mt-2 text-amber-700 bg-amber-50 rounded-lg text-xs';
        emptyInfo.innerHTML = '<svg class="w-4 h-4 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg><div>Belum ada data ' + f.l + '. ' + (f.emptyHint || 'Silakan isi data terlebih dahulu di menu terkait.') + '</div>';
        sel.parentNode.appendChild(emptyInfo);
      } else {
        sel.innerHTML = '<option value="">— Pilih ' + f.l + ' —</option>' +
          list.map(r => {
            var label = r[f.labelField || 'nama'];
            if (f.labelFormat) label = f.labelFormat.replace(/\{(\w+)\}/g, function(_, k) { return r[k] != null ? r[k] : ''; });
            return `<option value="${r[f.valueField || 'id']}" data-item='${encodeURIComponent(JSON.stringify(r))}' ${editing?.[f.k] == r[f.valueField || 'id'] ? 'selected' : ''}>${label}</option>`;
          }).join('');
      }
      sel.onchange = function() {
        const opt = sel.options[sel.selectedIndex];
        if (opt && opt.dataset.item) {
          const item = JSON.parse(decodeURIComponent(opt.dataset.item));
          if (f.fill) Object.keys(f.fill).forEach(key => {
            const src = document.getElementById('f-' + key);
            if (src) src.value = item[f.fill[key]] || '';
          });
          if (f.fillApi && item[f.fillApi.param]) {
            api.get(f.fillApi.url + '?kategori=' + encodeURIComponent(item[f.fillApi.param])).then(r => {
              const tgt = document.getElementById('f-' + f.fillApi.target);
              if (tgt && r.total) tgt.value = r.total;
            });
          }
        }
      };
    });
  });

  // Auto-calc fields (e.g. jumlah_penerima = porsi_besar + porsi_kecil, berat_kotor = berat_bersih / bdd_persen)
  cfg.fields.filter(function(f) { return f.calc; }).forEach(function(f) {
    var target = document.getElementById('f-' + f.k);
    if (!target) return;
    var srcDefs = (f.calc.from || []).map(function(src) {
      var el = document.getElementById('f-' + src);
      var def = cfg.fields.find(function(x) { return x.k === src; });
      return { el: el, isPct: def && def.fmt === 'pct' };
    }).filter(function(s) { return s.el; });
    if (srcDefs.length < 2) return;
    var dec = f.decimals != null ? f.decimals : 0;
    function updateCalc() {
      var vals = srcDefs.map(function(s) {
        var v = parseFloat(s.el.value) || 0;
        return s.isPct ? v / 100 : v;
      });
      var result;
      if (f.calc.op === 'add') {
        result = vals.reduce(function(a, b) { return a + b; }, 0);
      } else {
        var a = vals[0], b = vals[1];
        result = b !== 0 ? a / b : 0;
      }
      target.value = result.toFixed(dec);
    }
    srcDefs.forEach(function(s) { s.el.addEventListener('input', updateCalc); });
    updateCalc();
  });

  document.getElementById('modal-save').onclick = async () => {
    var rules = cfg.fields.filter(function(f) { return f.req; }).map(function(f) {
      return { id: 'f-' + f.k, label: f.l, type: (f.type === 'select' || f.type === 'select-api') ? 'select' : (f.type === 'number' ? 'number' : 'text') };
    });
    if (!validateForm(rules)) return;
    const payload = {};
    cfg.fields.forEach(f => {
      const v = document.getElementById('f-' + f.k).value;
      let val = v;
      if (f.type === 'number') {
        var _ns = String(v).trim();
        val = _ns.includes(',') ? Number(_ns.replace(/\./g, '').replace(',', '.')) : Number(_ns);
        if (isNaN(val)) val = 0;
      }
      if (f.fmt === 'pct') val = val / 100;
      payload[f.k] = val;
    });
    if (editing) await api.put(cfg.endpoint + '/' + editing.id, payload);
    else await api.post(cfg.endpoint, payload);
    closeModal();
    if (cfg.onSaved) cfg.onSaved();
    else reloadCrud(cfg);
  };
  document.getElementById('modal').classList.remove('hidden');
  document.getElementById('modal').classList.add('flex');
}
window.fillAiNutrisiSp = async function() {
  var namaEl = document.getElementById('f-nama');
  if (!namaEl || !namaEl.value.trim()) {
    showAlert('Isi Nama Bahan terlebih dahulu', 'warning');
    return;
  }
  var btn = document.querySelector('button[onclick="fillAiNutrisiSp()"]');
  if (btn) { btn.disabled = true; btn.textContent = '...'; }
  try {
    var res = await api.post('/ai/suggest-nutrisi', { nama: namaEl.value.trim() });
    var mapping = { energi: 'kalori', protein: 'protein', lemak: 'lemak', karbohidrat: 'karbohidrat', serat: 'serat' };
    (window._aiFields || []).forEach(function(f) {
      var el = document.getElementById('f-' + f.k);
      var srcKey = mapping[f.k];
      if (el && res[srcKey] != null) el.value = Number(res[srcKey]).toFixed(f.decimals != null ? f.decimals : 1);
    });
    showToast('Gizi terisi dari AI', 'success');
  } catch (e) {
    showAlert('Gagal: ' + e.message, 'error');
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Isi AI'; }
  }
};

function showConfirm(msg, okLabel, cancelLabel, okStyle, type) {
  return new Promise((resolve) => {
    const modal = document.getElementById('confirm-modal');
    const content = document.getElementById('confirm-content');
    const backdrop = modal.querySelector('.modal-backdrop');
    const iconWrap = document.getElementById('confirm-icon');
    const iconSvg = document.getElementById('confirm-icon-svg');
    const titleEl = document.getElementById('confirm-title');
    const okBtn = document.getElementById('confirm-ok');
    const cancelBtn = document.getElementById('confirm-cancel');

    const types = {
      warning: { bg: 'bg-amber-100', text: 'text-amber-600', icon: 'M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z', title: 'Perhatian', btn: 'bg-amber-600 hover:bg-amber-700' },
      danger: { bg: 'bg-red-100', text: 'text-red-600', icon: 'M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z', title: 'Konfirmasi Hapus', btn: 'bg-red-600 hover:bg-red-700' },
      info: { bg: 'bg-blue-100', text: 'text-blue-600', icon: 'M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z', title: 'Informasi', btn: 'bg-blue-600 hover:bg-blue-700' },
      success: { bg: 'bg-emerald-100', text: 'text-emerald-600', icon: 'M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z', title: 'Konfirmasi', btn: 'bg-emerald-600 hover:bg-emerald-700' },
      question: { bg: 'bg-purple-100', text: 'text-purple-600', icon: 'M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z', title: 'Konfirmasi', btn: 'bg-purple-600 hover:bg-purple-700' },
    };
    const t = types[type] || types.question;
    const isDark = document.documentElement.classList.contains('dark');
    const darkBg = { 'bg-amber-100': 'bg-[#451a03]', 'bg-red-100': 'bg-[#450a0a]', 'bg-blue-100': 'bg-[#1e3a5f]', 'bg-emerald-100': 'bg-[#064e3b]', 'bg-purple-100': 'bg-[#3b0764]' };
    const darkText = { 'text-amber-600': 'text-amber-300', 'text-red-600': 'text-red-300', 'text-blue-600': 'text-blue-300', 'text-emerald-600': 'text-emerald-300', 'text-purple-600': 'text-purple-300' };

    const open = () => {
      modal.classList.remove('hidden');
      modal.classList.add('flex');
      requestAnimationFrame(() => {
        backdrop.classList.remove('opacity-0');
        content.classList.remove('opacity-0', 'scale-95');
        content.classList.add('opacity-100', 'scale-100');
      });
      okBtn.focus();
      document.body.style.overflow = 'hidden';
    };

    const close = (result) => {
      backdrop.classList.add('opacity-0');
      content.classList.add('opacity-0', 'scale-95');
      content.classList.remove('opacity-100', 'scale-100');
      setTimeout(() => {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
        document.body.style.overflow = '';
        resolve(result);
      }, 200);
    };

    const handleKeydown = (e) => {
      if (e.key === 'Escape') close(false);
      if (e.key === 'Tab') {
        const focusable = modal.querySelectorAll('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])');
        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
        else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
      }
    };

    document.getElementById('confirm-message').textContent = msg;
    okBtn.textContent = okLabel || 'Hapus';
    cancelBtn.textContent = cancelLabel || 'Batal';

    if (okStyle) {
      okBtn.className = 'px-4 py-2 text-sm font-medium text-white rounded-lg transition-all duration-150 focus:ring-2 focus:ring-offset-2 ' + okStyle;
    } else {
      okBtn.className = 'px-4 py-2 text-sm font-medium text-white rounded-lg transition-all duration-150 focus:ring-2 focus:ring-offset-2 ' + (isDark ? t.btn.replace('hover:', 'hover:') : t.btn);
    }

    iconWrap.className = 'w-10 h-10 rounded-full flex items-center justify-center shrink-0 ' + (isDark ? darkBg[t.bg] : t.bg);
    iconSvg.className = 'w-5 h-5 ' + (isDark ? darkText[t.text] : t.text);
    iconSvg.querySelector('path').setAttribute('d', t.icon);
    titleEl.textContent = t.title;

    const cancelHandler = () => { modal.removeEventListener('keydown', handleKeydown); backdrop.removeEventListener('click', cancelHandler); close(false); };
    const okHandler = () => { modal.removeEventListener('keydown', handleKeydown); backdrop.removeEventListener('click', cancelHandler); close(true); };

    cancelBtn.onclick = cancelHandler;
    okBtn.onclick = okHandler;
    backdrop.onclick = cancelHandler;
    modal.addEventListener('keydown', handleKeydown);

    open();
  });
}

function showAlert(msg, type) {
  var modal = document.getElementById('alert-modal');
  if (!modal) return;
  var titleEl = document.getElementById('alert-title');
  var msgEl = document.getElementById('alert-message');
  var iconWrap = document.getElementById('alert-icon');
  var svgEl = document.getElementById('alert-svg');
  var okBtn = document.getElementById('alert-ok');
  var colors = {
    warning: { bg: 'bg-amber-100', text: 'text-amber-600', btn: 'bg-amber-600 hover:bg-amber-700', icon: 'M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z', title: 'Perhatian' },
    error: { bg: 'bg-red-100', text: 'text-red-600', btn: 'bg-red-600 hover:bg-red-700', icon: 'M10 14l2-2m0 0l2-2m-2 2l-2-2m2 2l2 2m7-2a9 9 0 11-18 0 9 9 0 0118 0z', title: 'Error' },
    success: { bg: 'bg-emerald-100', text: 'text-emerald-600', btn: 'bg-emerald-600 hover:bg-emerald-700', icon: 'M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z', title: 'Berhasil' },
  };
  var isDark = document.documentElement.classList.contains('dark');
  var c = colors[type] || colors.warning;
  if (isDark) {
    var darkMap = { 'bg-amber-100': 'bg-[#451a03]', 'bg-red-100': 'bg-[#450a0a]', 'bg-emerald-100': 'bg-[#064e3b]' };
    var textDarkMap = { 'text-amber-600': 'text-amber-300', 'text-red-600': 'text-red-300', 'text-emerald-600': 'text-emerald-300' };
    iconWrap.className = 'w-10 h-10 rounded-full ' + (darkMap[c.bg] || c.bg) + ' flex items-center justify-center shrink-0';
    svgEl.className = 'w-5 h-5 ' + (textDarkMap[c.text] || c.text);
  } else {
    iconWrap.className = 'w-10 h-10 rounded-full ' + c.bg + ' flex items-center justify-center shrink-0';
    svgEl.className = 'w-5 h-5 ' + c.text;
  }
  (svgEl.querySelector('path') || svgEl).setAttribute('d', c.icon);
  titleEl.textContent = c.title;
  msgEl.textContent = msg;
  okBtn.className = 'px-5 py-2 text-sm font-medium text-white rounded-lg transition-colors ' + c.btn;
  okBtn.onclick = function() {
    modal.classList.add('hidden');
    modal.classList.remove('flex');
  };
  modal.classList.remove('hidden');
  modal.classList.add('flex');
}

function validateForm(rules) {
  for (var i = 0; i < rules.length; i++) {
    var r = rules[i];
    var el = document.getElementById(r.id);
    if (!el) continue;
    var val = el.value;
    if (r.type === 'select' && !val) {
      showAlert(r.label + ' harus dipilih', 'warning');
      el.focus();
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return false;
    }
    if (r.type === 'number') {
      if (val === '' || Number(val) === 0) {
        showAlert(r.label + ' harus diisi', 'warning');
        el.focus();
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        return false;
      }
      continue;
    }
    if (!val || !val.trim()) {
      showAlert(r.label + ' harus diisi', 'warning');
      el.focus();
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
      return false;
    }
  }
  return true;
}

function showToast(msg, type) {
  var c = document.getElementById('toast-container');
  if (!c) return;
  var colors = { success: 'bg-emerald-600', error: 'bg-red-600', warning: 'bg-amber-500' };
  var el = document.createElement('div');
  el.className = (colors[type] || 'bg-stone-800') + ' text-white px-4 py-2.5 rounded-lg text-sm shadow-lg pointer-events-auto animate-alert-in';
  el.textContent = msg;
  c.appendChild(el);
  setTimeout(function() {
    el.style.opacity = '0';
    el.style.transition = 'opacity 0.3s';
    setTimeout(function() { el.remove(); }, 300);
  }, 3000);
}

function showCrudInfo() {
  var cfg = window._crudInfoCfg;
  if (!cfg || !cfg.helpContent) return;
  var existing = document.getElementById('crud-info-popup');
  if (existing) { existing.remove(); return; }
  var hc = cfg.helpContent;
  var div = document.createElement('div');
  div.id = 'crud-info-popup';
  div.className = 'fixed inset-0 z-[70] flex items-center justify-center bg-black/30';
  div.innerHTML = '<div class="bg-white rounded-2xl shadow-xl max-w-md w-full mx-4 p-6" onclick="event.stopPropagation()">' +
    '<div class="flex items-center justify-between mb-4">' +
      '<div class="flex items-center gap-3">' +
        '<div class="w-10 h-10 rounded-xl bg-blue-100 flex items-center justify-center text-blue-600">' + (cfg.icon || '<svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>') + '</div>' +
        '<div><h3 class="font-bold text-stone-700">' + (cfg.title || 'Halaman Ini') + '</h3><p class="text-xs text-stone-400">' + (cfg.subtitle || '') + '</p></div>' +
      '</div>' +
      '<button onclick="document.getElementById(\'crud-info-popup\').remove()" class="text-stone-400 hover:text-stone-600"><svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M18 6L6 18M6 6l12 12"/></svg></button>' +
    '</div>' +
    '<div class="space-y-4 text-sm text-stone-600">' +
      hc.map(function(item, idx) {
        return '<div class="flex gap-3 items-start">' +
          '<span class="shrink-0 w-7 h-7 rounded-full bg-blue-100 text-blue-700 flex items-center justify-center text-xs font-bold">' + (idx + 1) + '</span>' +
          '<div><span class="font-semibold text-stone-700">' + item.title + '</span><br>' + item.text + '</div>' +
        '</div>';
      }).join('') +
    '</div>' +
    '<div class="mt-4 pt-3 border-t border-stone-100 flex justify-end">' +
      '<button onclick="document.getElementById(\'crud-info-popup\').remove()" class="px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors">Mengerti</button>' +
    '</div>' +
  '</div>';
  div.onclick = function() { div.remove(); };
  document.body.appendChild(div);
}

function closeModal(id) {
  // Restore modal footer if hidden by wizard
  var saveBtn = document.getElementById('modal-save');
  if (saveBtn) saveBtn.style.display = '';
  var footer = document.querySelector('#modal > div > div.border-t.flex.justify-end:last-child');
  if (footer) footer.style.display = '';
  
  var m = document.getElementById(id || 'modal');
  if (m) { m.classList.add('hidden'); m.classList.remove('flex'); }
}

// Recalculate budget realisasi from actual transactions
async function recalculateRealisasi() {
  if (!await showConfirm('Hitung ulang realisasi budget dari transaksi kas bank?', 'Ya, Hitung')) return;
  try {
    const r = await api.post('/budget/recalculate-realisasi');
    showAlert(`Berhasil: ${r.updated} budget diupdate dari ${r.total_periode} periode`, 'success');
    if (typeof reloadCrud === 'function' && _crudCfg) reloadCrud(_crudCfg);
  } catch (e) {
    showAlert('Gagal: ' + e.message, 'error');
  }
}

// Backfill journal entries for existing paid PO & Payroll
async function backfillJournal() {
  if (!await showConfirm('Buat entry kas_bank untuk PO & Payroll yang sudah Dibayar sebelumnya?', 'Ya, Backfill')) return;
  try {
    const r = await api.post('/keuangan/backfill-journal');
    showAlert(`Berhasil: ${r.created} entry kas_bank dibuat`, 'success');
  } catch (e) {
    showAlert('Gagal: ' + e.message, 'error');
  }
}

// Tanya AI — generate teks dari field lain (misal nama) → isi textarea
window.tanyaAi = async function(fieldId, sourceField) {
  var nameEl = sourceField ? document.getElementById('f-' + sourceField) : null;
  var name = nameEl ? nameEl.value.trim() : '';
  var q;
  if (name) {
    q = 'Inti "' + name + '" dapur MBG:';
  } else {
    q = prompt('Apa yang ingin Anda tanyakan?');
    if (!q) return;
  }
  var textarea = document.getElementById('f-' + fieldId);
  if (!textarea) return;
  textarea.value = 'Menulis...';
  try {
    var resp = await api.post('/ai/tanya', { prompt: q });
    textarea.value = resp.text || '';
  } catch (e) {
    textarea.value = 'Error: ' + (e.message || 'Gagal');
  }
};

// ===== Surat Jalan Distribusi =====
async function cetakSuratJalan(id) {
  try {
    var res = await api.get('/distribusi/' + id);
    var d = res.id ? res : (res.data || res);
    if (!d || !d.id) throw new Error('Data tidak ditemukan');
    var tgl = fmtDate(d.tanggal_distribusi) || d.tanggal_distribusi;
    var no = 'SJ/' + String(d.id).padStart(4, '0') + '/' + (d.tanggal_distribusi ? d.tanggal_distribusi.slice(0, 7).replace('-', '/') : '');
    var html = '<html><head><meta charset="utf-8"><title>Surat Jalan</title>' +
      '<style>' +
      'body{font-family:Arial,sans-serif;margin:0;padding:40px;color:#1c1917}' +
      '.kop{text-align:center;border-bottom:2px solid #1c1917;padding-bottom:12px;margin-bottom:24px}' +
      '.kop h1{margin:0;font-size:18px;text-transform:uppercase;letter-spacing:1px}' +
      '.kop p{margin:2px 0;font-size:12px;color:#57534e}' +
      'h2{text-align:center;font-size:14px;text-transform:uppercase;letter-spacing:1px;margin:0 0 20px}' +
      'table.detail{width:100%;border-collapse:collapse;margin-bottom:24px}' +
      'table.detail td{padding:4px 8px;font-size:12px;vertical-align:top}' +
      'table.detail td.label{width:120px;font-weight:700;color:#57534e}' +
      'table.detail td.sep{width:12px;text-align:center}' +
      'table.items{width:100%;border-collapse:collapse;margin-bottom:32px}' +
      'table.items th{background:#f5f5f4;font-size:11px;text-transform:uppercase;padding:8px;text-align:left;border:1px solid #d6d3d1}' +
      'table.items td{font-size:12px;padding:8px;border:1px solid #d6d3d1}' +
      '.ttd{display:flex;justify-content:space-between;margin-top:48px}' +
      '.ttd div{text-align:center;width:200px}' +
      '.ttd .line{margin-top:48px;padding-top:4px;border-top:1px solid #1c1917;font-size:11px}' +
      '@media print{body{padding:20px}}' +
      '</style></head><body>' +
      '<div class="kop"><h1>DAPUR SUKALUYU</h1><p>Jl. Contoh No. 123, Kota Sukaluyu</p><p>Telp: (0265) 123456</p></div>' +
      '<h2>SURAT JALAN</h2>' +
      '<table class="detail">' +
      '<tr><td class="label">No. Surat Jalan</td><td class="sep">:</td><td>' + no + '</td></tr>' +
      '<tr><td class="label">Tanggal</td><td class="sep">:</td><td>' + tgl + '</td></tr>' +
      '<tr><td class="label">Kepada</td><td class="sep">:</td><td><strong>' + (d.pm_nama || d.nama_kelompok || '-') + '</strong></td></tr>' +
      '<tr><td class="label">Alamat</td><td class="sep">:</td><td>' + (d.pm_alamat || d.lokasi || '-') + '</td></tr>' +
      '<tr><td class="label">Kategori</td><td class="sep">:</td><td>' + (d.kategori_penerima || '-') + '</td></tr>' +
      (d.kurir ? '<tr><td class="label">Kurir / Driver</td><td class="sep">:</td><td>' + d.kurir + '</td></tr>' : '') +
      '</table>' +
      '<table class="items"><thead><tr><th style="width:40px">No</th><th>Deskripsi</th><th style="width:100px;text-align:center">Jumlah</th><th style="width:80px;text-align:center">Satuan</th></tr></thead><tbody>' +
      '<tr><td style="text-align:center">1</td><td>Paket Makanan ' + (d.kategori_penerima || '') + '</td><td style="text-align:center">' + fmtNum(d.jumlah_porsi || 0) + '</td><td style="text-align:center">Porsi</td></tr>' +
      '</tbody></table>' +
      (d.catatan ? '<p style="font-size:11px;color:#57534e;margin-bottom:24px">Catatan: ' + d.catatan + '</p>' : '') +
      '<div class="ttd">' +
      '<div><div>Pengirim</div><div class="line">( ' + (d.kurir || '________') + ' )</div></div>' +
      '<div><div>Mengetahui</div><div class="line">( ______________ )</div></div>' +
      '<div><div>Penerima</div><div class="line">( ______________ )</div></div>' +
      '</div></body></html>';
    var w = window.open('', '_blank');
    w.document.write(html);
    w.document.close();
    w.print();
  } catch (e) {
    showAlert('Gagal memuat data: ' + e.message, 'error');
  }
}

async function renderDashboard() {
  const c = document.getElementById('content');
  c.innerHTML = '<div class="flex items-center justify-center py-24"><svg class="animate-spin h-10 w-10 text-[#1e40af]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg></div>';
  try {
    const r = await fetch('/api/template/dashboard', { credentials: 'include' });
    if (!r.ok) {
      const err = await r.json();
      throw new Error(err.error || 'Gagal memuat dashboard');
    }
    c.innerHTML = await r.text();
  } catch (err) {
    console.error('Dashboard error:', err);
    c.innerHTML = `<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal memuat dashboard: ${err.message}</div>`;
  }
}

/**
 * renderDashboardKeuangan - Dashboard Keuangan
 * Menampilkan ringkasan keuangan: saldo kas, pendapatan/biaya bulan ini, transaksi terbaru
 */
async function renderDashboardKeuangan() {
  const c = document.getElementById('content');
  c.innerHTML = '<div class="flex items-center justify-center py-24"><svg class="animate-spin h-8 w-8 text-[#1e40af]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg></div>';

  try {
    const d = await api.get('/dashboard/finance');

    const fmtIDR = (v) => 'Rp' + Number(v || 0).toLocaleString('id-ID');
    const fmtNum = (v) => Number(v || 0).toLocaleString('id-ID');
    const fmtDate = (s) => {
      if (!s) return '-';
      const d = new Date(s);
      return isNaN(d.getTime()) ? '-' : d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
    };

    // Helper untuk badge growth
    const growthBadge = (pct) => {
      if (pct === null) return '<span class="text-[10px] text-stone-400">—</span>';
      const isPos = pct >= 0;
      return `<span class="text-[10px] font-medium ${isPos ? 'text-emerald-600' : 'text-red-600'}">${isPos ? '↑' : '↓'} ${Math.abs(pct)}%</span>`;
    };

    const labaClass = d.laba_rugi >= 0 ? 'text-emerald-600' : 'text-red-600';
    const labaLabel = d.laba_rugi >= 0 ? 'Laba' : 'Rugi';

    // Stat cards
    const statCards = [
      { label: 'Saldo Kas', value: fmtIDR(d.saldo_kas), gradient: 'from-emerald-50 to-emerald-100/60', border: 'border-emerald-200/60', icon: 'circle', iconColor: 'text-emerald-500', textColor: 'text-emerald-800', extra: '' },
      { label: 'Pendapatan Bulan Ini', value: fmtIDR(d.pendapatan_bulan_ini), gradient: 'from-blue-50 to-blue-100/60', border: 'border-blue-200/60', icon: 'arrow-up', iconColor: 'text-blue-500', textColor: 'text-blue-800', extra: `${growthBadge(d.pendapatan_growth)} <span class="text-[10px] text-stone-400">vs bulan lalu</span>` },
      { label: 'Biaya Bulan Ini', value: fmtIDR(d.biaya_bulan_ini), gradient: 'from-orange-50 to-orange-100/60', border: 'border-orange-200/60', icon: 'arrow-down', iconColor: 'text-orange-500', textColor: 'text-orange-800', extra: `${growthBadge(d.biaya_growth)} <span class="text-[10px] text-stone-400">vs bulan lalu</span>` },
      { label: `${labaLabel} Bulan Ini`, value: fmtIDR(Math.abs(d.laba_rugi)), gradient: d.laba_rugi >= 0 ? 'from-emerald-50 to-emerald-100/60' : 'from-red-50 to-red-100/60', border: d.laba_rugi >= 0 ? 'border-emerald-200/60' : 'border-red-200/60', icon: 'dollar', iconColor: labaClass, textColor: labaClass, extra: `<span class="text-[10px] text-stone-500">Margin: ${d.margin}%</span>` },
    ];
    let html = `<div class="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-6">`;
    statCards.forEach(c => {
      const iconSvg = {
        'circle': '<circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/>',
        'arrow-up': '<path d="M12 19V5m0 0l-7 7m7-7l7 7"/>',
        'arrow-down': '<path d="M12 5v14m0 0l7-7m-7 7l-7-7"/>',
        'dollar': '<path d="M12 2v20M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>',
      }[c.icon];
      html += `
      <div class="bg-gradient-to-br ${c.gradient} rounded-2xl border ${c.border} p-4 sm:p-5 shadow-sm">
        <div class="flex items-center justify-between mb-2">
          <span class="text-[10px] font-semibold uppercase tracking-wider ${c.textColor}">${c.label}</span>
          <svg class="w-4 h-4 ${c.iconColor}" fill="none" stroke="currentColor" viewBox="0 0 24 24">${iconSvg}</svg>
        </div>
        <div class="mono text-xl sm:text-2xl font-bold ${c.textColor}">${c.value}</div>
        ${c.extra ? `<div class="mt-1">${c.extra}</div>` : ''}
      </div>`;
    });
    html += `</div>`;

    // Low stock alert
    if (d.stok_menipis > 0) {
      html += `
      <div class="bg-amber-50 border border-amber-200 rounded-2xl p-4 mb-6 flex items-center gap-3 shadow-sm">
        <div class="w-9 h-9 rounded-full bg-amber-100 flex items-center justify-center shrink-0">
          <svg class="w-5 h-5 text-amber-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 9v2m0 4h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z"/></svg>
        </div>
        <div class="text-sm">
          <span class="font-semibold text-amber-800">${d.stok_menipis} bahan baku</span>
          <span class="text-amber-700">dengan stok menipis. </span>
          <a href="/gudang" data-key="gudang" class="font-medium text-amber-800 underline hover:no-underline">Cek Gudang →</a>
        </div>
      </div>`;
    }

    // Recent transactions table
    const transaksi = d.transaksi_terbaru || [];
    html += `
    <div class="bg-white rounded-2xl border border-stone-200 shadow-sm overflow-hidden">
      <div class="px-4 sm:px-5 py-3 sm:py-4 border-b border-stone-200 flex items-center justify-between">
        <h3 class="font-bold text-sm text-stone-800">Transaksi Terbaru</h3>
        <span class="text-[10px] font-medium text-stone-500">${d.bulan}/${d.tahun}</span>
      </div>
      <div class="overflow-x-auto">
        <table class="w-full">
          <thead>
            <tr class="border-b border-stone-100">
              <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Tanggal</th>
              <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Tipe</th>
              <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Kategori</th>
              <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Deskripsi</th>
              <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Jumlah</th>
            </tr>
          </thead>
          <tbody>`;

    if (transaksi.length === 0) {
      html += '<tr><td colspan="5" class="text-center py-12 text-stone-400">Belum ada transaksi</td></tr>';
    } else {
      transaksi.forEach(t => {
        const isMasuk = t.tipe === 'masuk';
        const tipeClass = isMasuk ? 'text-emerald-600' : 'text-red-600';
        const badgeBg = isMasuk ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700';
        html += `
          <tr class="border-b border-stone-50 hover:bg-stone-50/50 transition-colors">
            <td class="px-4 py-3 mono text-[10px] text-stone-600">${fmtDate(t.tanggal)}</td>
            <td class="px-4 py-3">
              <span class="inline-block px-2.5 py-0.5 text-[10px] font-semibold rounded-lg ${badgeBg}">${t.tipe}</span>
            </td>
            <td class="px-4 py-3 text-xs text-stone-600">${t.kategori || '-'}</td>
            <td class="px-4 py-3 text-xs text-stone-600 max-w-[200px] truncate">${escHtml(t.deskripsi || '-')}</td>
            <td class="px-4 py-3 text-right mono text-xs font-semibold ${tipeClass}">${fmtIDR(t.jumlah)}</td>
          </tr>`;
      });
    }

    html += `
          </tbody>
        </table>
      </div>
    </div>`;

    c.innerHTML = html;
  } catch (err) {
    console.error('Dashboard Keuangan error:', err);
    c.innerHTML = `<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal memuat dashboard keuangan: ${err.message}</div>`;
  }
}

// ===== Menu (custom with bahan) =====
let menuState = { page: 1, limit: 10, search: '', total: 0, totalPages: 1 };
let menuViewMode = 'list'; // 'list' | 'siklus'

async function ensureBahanBakuLoaded() {
  if (window._bahanBaku) return;
  const [bahan, spRef] = await Promise.all([
    api.get('/bahan_baku'),
    api.get('/sp_referensi_bahan').catch(() => []),
  ]);
  window._bahanBaku = bahan;
  window._spRefList = Array.isArray(spRef) ? spRef : [];
  window._spRefMap = {};
  (window._spRefList || []).forEach(function(r) {
    window._spRefMap[r.nama] = {
      berat_bersih: Number(r.berat_bersih),
      bdd_persen: Number(r.bdd_persen),
      energi: Number(r.energi) || 0,
      protein: Number(r.protein) || 0,
      lemak: Number(r.lemak) || 0,
      karbohidrat: Number(r.karbohidrat) || 0,
      serat: Number(r.serat) || 0,
    };
  });
}

async function renderMenu() {
  const c = document.getElementById('content');
  if (!c) return;
  c.innerHTML = '<div class="flex items-center justify-center py-24"><svg class="animate-spin h-10 w-10 text-[#1e40af]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg></div>';
  try {
    if (menuViewMode === 'siklus') {
      await ensureBahanBakuLoaded();
      await renderMenuBySiklus(c);
      return;
    }

    const params = new URLSearchParams({ page: menuState.page, limit: menuState.limit, search: menuState.search });
    const r = await fetch('/api/menu?' + params, { credentials: 'include' });
    if (!r.ok) {
      const err = await r.json().catch(() => ({}));
      throw new Error(err.error || 'Gagal memuat menu');
    }
    const data = await r.json();
    const pagination = data.pagination || { total: data.length || 0, totalPages: 1, page: menuState.page };
    menuState = { ...menuState, total: pagination.total, totalPages: pagination.totalPages, page: pagination.page };
    
    c.innerHTML = renderMenuHtml(Array.isArray(data.data) ? data.data : (Array.isArray(data) ? data : []));
    renderPagination();
    attachMenuHandlers();
  } catch (err) {
    console.error('Menu error:', err);
    c.innerHTML = `<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal memuat menu: ${err.message}</div>`;
  }
}

async function renderMenuBySiklus(c) {
  try {
    const r = await fetch('/api/menu/by-siklus', { credentials: 'include' });
    if (!r.ok) throw new Error('Gagal memuat data');
    const data = await r.json();
    c.innerHTML = renderMenuBySiklusHtml(data);
    attachMenuBySiklusHandlers();
  } catch (err) {
    console.error('Menu by siklus error:', err);
    c.innerHTML = `<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal memuat menu berdasarkan siklus: ${err.message}</div>`;
  }
}

function renderMenuBySiklusHtml(data) {
  const groups = data.siklus_groups || [];
  const standalone = data.standalone || [];
  const totalMenu = data.total_menu || 0;
  const usedInSiklus = data.used_in_siklus || 0;

  // Tab navigation
  const tabsHtml = `<div class="flex items-center gap-1 mb-5 bg-stone-100 rounded-xl p-1 w-fit border border-stone-200">
    <button onclick="switchMenuView('list')" class="px-4 py-2 text-sm font-medium rounded-lg transition-all ${menuViewMode === 'list' ? 'bg-white text-stone-900 shadow-sm border border-stone-200' : 'text-stone-500 hover:text-stone-700'}">
      <svg class="w-4 h-4 inline -mt-0.5 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M3 3h18v18H3z"/><path d="M3 9h18"/><path d="M3 15h18"/><path d="M9 3v18"/></svg>
      Semua Menu
    </button>
    <button onclick="switchMenuView('siklus')" class="px-4 py-2 text-sm font-medium rounded-lg transition-all ${menuViewMode === 'siklus' ? 'bg-white text-stone-900 shadow-sm border border-stone-200' : 'text-stone-500 hover:text-stone-700'}">
      <svg class="w-4 h-4 inline -mt-0.5 mr-1.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
      Berdasarkan Siklus
    </button>
  </div>`;

  // Stats cards
  const statsHtml = `<div class="flex flex-wrap gap-3 mb-6">
    <div class="flex-1 min-w-[140px] bg-gradient-to-br from-blue-50 to-blue-100/60 rounded-2xl border border-blue-200/60 px-4 py-3 shadow-sm"><div class="text-[10px] font-semibold uppercase tracking-wider text-blue-700 mb-0.5">Total Menu</div><div class="text-xl font-bold text-blue-800">${totalMenu}</div></div>
    <div class="flex-1 min-w-[140px] bg-gradient-to-br from-sky-50 to-sky-100/60 rounded-2xl border border-sky-200/60 px-4 py-3 shadow-sm"><div class="text-[10px] font-semibold uppercase tracking-wider text-sky-700 mb-0.5">Digunakan di Siklus</div><div class="text-xl font-bold text-sky-800">${usedInSiklus}</div></div>
    <div class="flex-1 min-w-[140px] bg-gradient-to-br from-emerald-50 to-emerald-100/60 rounded-2xl border border-emerald-200/60 px-4 py-3 shadow-sm"><div class="text-[10px] font-semibold uppercase tracking-wider text-emerald-700 mb-0.5">Standalone</div><div class="text-xl font-bold text-emerald-800">${standalone.length}</div></div>
    <div class="flex-1 min-w-[140px] bg-gradient-to-br from-amber-50 to-amber-100/60 rounded-2xl border border-amber-200/60 px-4 py-3 shadow-sm"><div class="text-[10px] font-semibold uppercase tracking-wider text-amber-700 mb-0.5">Siklus Aktif</div><div class="text-xl font-bold text-amber-800">${groups.filter(g => g.status === 'Aktif').length}</div></div>
  </div>`;

  // Siklus groups
  let siklusHtml = '';
  if (groups.length === 0) {
    siklusHtml = `<div class="col-span-full text-center py-12 text-stone-400">
      <svg class="w-14 h-14 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
      <div>Belum ada siklus menu</div>
      <div class="text-sm mt-1">Buat siklus terlebih dahulu untuk mengelompokkan menu</div>
      <a href="/siklus" onclick="return loadPage('siklus')" class="inline-flex items-center gap-1.5 mt-4 px-4 py-2 text-xs font-semibold rounded-lg bg-blue-600 text-white hover:bg-blue-700 transition-colors shadow-sm">
        <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 4v16m8-8H4"/></svg>
        Buat Siklus Baru
      </a>
    </div>`;
  } else {
    siklusHtml = groups.map(s => {
      const statusColor = s.status === 'Aktif' ? 'bg-emerald-100 text-emerald-800' : s.status === 'Draft' ? 'bg-amber-100 text-amber-800' : 'bg-stone-100 text-stone-600';
      const filledDays = s.days.filter(d => d.menu_id || d._has_content).length;
      const coverage = s.total_hari ? Math.round((filledDays / s.total_hari) * 100) : 0;

      return `<div class="bg-white border border-stone-200 rounded-2xl shadow-sm overflow-hidden">
        <!-- Siklus Header -->
        <div class="px-5 py-4 border-b border-stone-100 flex flex-wrap items-center justify-between gap-3">
          <div>
            <div class="flex items-center gap-2">
              <h3 class="font-bold text-stone-800">${s.nama}</h3>
              <span class="text-[10px] px-2.5 py-1 rounded-full font-medium ${statusColor} capitalize">${s.status}</span>
            </div>
            <div class="flex flex-wrap items-center gap-3 mt-1 text-xs text-stone-500">
              <span>${s.kategori_penerima || 'Semua'}</span>
              <span>${s.jumlah_porsi} porsi/hari</span>
              <span>${s.total_hari} hari</span>
              <span class="${coverage >= 100 ? 'text-emerald-600 font-semibold' : coverage > 0 ? 'text-amber-600' : 'text-stone-400'}">${coverage}% terisi</span>
              <span>${s.menu_count} menu unik</span>
            </div>
          </div>
          <a href="#" onclick="navigate('siklus');return false" class="text-xs text-[#1e40af] hover:text-[#1d4ed8] font-medium hover:underline whitespace-nowrap">
            Kelola Siklus →
          </a>
        </div>
        ${s.status === 'Draft' ? `
        <!-- Draft Info -->
        <div class="px-4 pb-4">
          <div class="bg-amber-50 border-2 border-amber-200/80 rounded-xl p-5 text-center shadow-sm">
            <div class="w-12 h-12 mx-auto mb-3 rounded-full bg-amber-100 flex items-center justify-center">
              <svg class="w-6 h-6 text-amber-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L4.082 16.5c-.77.833.192 2.5 1.732 2.5z"/></svg>
            </div>
            <h4 class="text-sm font-bold text-amber-800 mb-1.5">Siklus Masih Draft</h4>
            <p class="text-xs text-amber-700/80 max-w-sm mx-auto leading-relaxed">Siklus <strong>${s.nama}</strong> masih berstatus <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-amber-200/60 text-amber-800 font-semibold text-[10px]">DRAFT</span>. Silakan aktifkan siklus terlebih dahulu untuk mengelola menu dan bahan baku.</p>
            <a href="#" onclick="navigate('siklus');return false" class="inline-flex items-center gap-1.5 mt-3 px-4 py-2 text-xs font-medium text-amber-700 bg-white border border-amber-200 rounded-lg hover:bg-amber-50 transition-colors shadow-sm">
              <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 4v16m8-8H4"/></svg>
              Aktifkan Siklus
            </a>
          </div>
        </div>
        ` : `
        <!-- Days Grid -->
        <div class="p-4">
          <div class="grid gap-3" style="grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));">
            ${s.days.map(d => {
              const isFilled = d.menu_id || d._has_content;
              return `<div class="border rounded-lg p-3 transition-all ${isFilled ? (d.menu_id ? 'border-stone-200 hover:border-[#1e40af]/30 hover:shadow-sm' : 'border-emerald-200 bg-emerald-50/30 hover:border-emerald-300 hover:shadow-sm') : 'border-dashed bg-stone-50/50'} ">
                <div class="flex items-center justify-between mb-2">
                  <span class="text-[10px] font-semibold uppercase text-stone-400">Hari ${d.hari_ke}</span>
                  <span class="text-[10px] text-stone-400">${d.hari_nama}</span>
                </div>
                ${isFilled ? `
                  <div class="font-medium text-sm text-stone-800 truncate" title="${d.menu_nama}">${d.menu_nama}</div>
                  <div class="flex items-center gap-2 mt-1.5 text-[10px] text-stone-500">
                    <span>${d.jumlah_porsi} porsi</span>
                    ${d.kalori ? `<span class="mono">${fmtNum(d.kalori)} kkal</span>` : ''}
                    ${d.gramasi_total ? `<span class="mono">${fmtNum(d.gramasi_total)}g</span>` : ''}
                    ${!d.menu_id && d._has_content ? '<span class="text-emerald-600 font-medium">Resep</span>' : ''}
                  </div>
                ` : `<div class="text-sm text-stone-400 italic">Belum diisi</div>`}
              </div>`;
            }).join('')}
          </div>
        </div>
        `}
      </div>`;
    }).join('<div class="h-3"></div>');
  }

  // Standalone menus section
  let standaloneHtml = '';
  if (standalone.length > 0) {
    standaloneHtml = `<div class="mt-6">
      <div class="flex items-center gap-2 mb-3">
        <h3 class="font-bold text-stone-700">Menu Tidak Terpakai</h3>
        <span class="bg-stone-100 text-stone-500 text-xs px-2.5 py-0.5 rounded-full font-medium">${standalone.length}</span>
      </div>
      <div class="bg-white border border-stone-200 rounded-2xl shadow-sm overflow-hidden">
        <div class="overflow-x-auto">
          <table class="w-full">
            <thead>
              <tr class="border-b border-stone-100">
                <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Nama</th>
                <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Kategori</th>
                <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Gramasi</th>
                <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Kalori</th>
                <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Protein</th>
                <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Karbo</th>
                <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Aksi</th>
              </tr>
            </thead>
            <tbody>
              ${standalone.length > 0 ? standalone.map(m => `
                <tr class="border-b border-stone-50 hover:bg-stone-50/50 transition-colors">
                  <td class="px-4 py-3 text-xs font-medium text-stone-700">
                    <div class="flex items-center gap-2">
                      <span class="truncate max-w-[180px]" title="${m.nama}">${m.nama}</span>
                    </div>
                  </td>
                  <td class="px-4 py-3 text-xs whitespace-nowrap">${m.kategori_penerima ? kategoriBadge(m.kategori_penerima) : '-'}</td>
                  <td class="px-4 py-3 text-xs text-right mono whitespace-nowrap text-stone-600">${renderGramasiCell(m.gramasi_total, m.bahan)}</td>
                  <td class="px-4 py-3 text-xs text-right mono whitespace-nowrap text-stone-600">${m.kalori}</td>
                  <td class="px-4 py-3 text-xs text-right mono whitespace-nowrap text-stone-600">${m.protein}</td>
                  <td class="px-4 py-3 text-xs text-right mono whitespace-nowrap text-stone-600">${m.karbohidrat}</td>
                 <td class="px-4 py-3 text-xs text-right">
                    <button onclick="switchMenuView('list');editMenuById(${m.id})" class="w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-blue-600 hover:bg-blue-50 transition-all" title="Edit"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
                    <button onclick="switchMenuView('list');saveCurrentMenuForPO({id: ${m.id}, nama: '${m.nama}', kategori_penerima: '${m.kategori_penerima}', jumlah_porsi: ${m.jumlah_porsi || 0}, gramasi_total: ${m.gramasi_total}, kalori: ${m.kalori}, protein: ${m.protein}, karbohidrat: ${m.karbohidrat}, lemak: ${m.lemak}, serat: ${m.serat}, bahan: ${JSON.stringify(m.bahan || [])}, status: '${m.status}'}); openMenuPoModal();" class="w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-emerald-600 hover:bg-emerald-50 transition-all" title="Buat PO"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>
                 </td>
               </tr>
              `).join('') : ''}
            </tbody>
          </table>
        </div>
      </div>
    </div>`;
  }

  return `<div>
    ${tabsHtml}
    ${statsHtml}
    ${siklusHtml}
    ${standaloneHtml}
  </div>`;
}

function attachMenuBySiklusHandlers() {
  const addBtn = document.getElementById('add-menu-btn');
  if (addBtn) addBtn.onclick = () => openMenuForm(null);
}

function switchMenuView(mode) {
  menuViewMode = mode;
  renderMenu();
}

async function editMenuById(id) {
  try {
    const menu = await api.get('/menu/' + id);
    openMenuForm(menu);
  } catch (e) {
    showAlert('Gagal memuat menu: ' + e.message, 'error');
  }
}

const KATEGORI_COLORS = {
  'TK/PAUD': { bg: '#0e7490' },
  'SD 1-3': { bg: '#0891b2' },
  'SD 4-6': { bg: '#d97706' },
  'SMP': { bg: '#1d4ed8' },
  'SMA': { bg: '#7c3aed' },
  'Ibu Hamil': { bg: '#be123c' },
  'Ibu Menyusui': { bg: '#6d28d9' },
  'Balita': { bg: '#0d9488' },
  'Posyandu': { bg: '#a21caf' },
  // backward compat
  'Paket Kecil': { bg: '#0e7490' },
};

function kategoriBadge(kat) {
  const c = KATEGORI_COLORS[kat] || { bg: '#78716c' };
  return `<span class="inline-block px-2.5 py-0.5 rounded-full text-xs font-medium text-white" style="background:${c.bg};">${kat}</span>`;
}

function renderBahanCell(bahan) {
  if (!bahan || !bahan.length) {
    return '<span class="text-stone-300">-</span>';
  }
  const names = bahan.map(function(b) { return b.nama; }).filter(Boolean);
  if (!names.length) {
    return '<span class="text-stone-300">-</span>';
  }
  const count = names.length;
  var display = names.slice(0, 2).join(', ');
  if (count > 2) display += ', ...';
  return '<span class="inline-flex items-center gap-1.5" title="' + escHtml(names.join(', ')) + '">' +
    '<span class="truncate max-w-[140px] block text-stone-600">' + escHtml(display) + '</span>' +
    '<span class="shrink-0 bg-stone-100 text-stone-500 text-[10px] font-medium px-1.5 py-0.5 rounded-full">' + count + '</span>' +
  '</span>';
}

function sumBahanGramasi(bahan) {
  if (!bahan || !bahan.length) return 0;
  return bahan.reduce(function(sum, b) { return sum + (Number(b.jumlah) || 0); }, 0);
}

function renderGramasiCell(gramasiTotal, bahan) {
  var displayGramasi = Number(gramasiTotal) || 0;
  var calculated = sumBahanGramasi(bahan);
  if (displayGramasi === 0 && calculated > 0) {
    displayGramasi = calculated;
  }
  if (displayGramasi === 0) {
    return '<span class="text-stone-300 cursor-help" title="Gramasi 0 karena menu belum memiliki bahan atau jumlah bahan belum diisi. Tambah bahan & pilih dari SP Referensi untuk isi otomatis.">0g</span>';
  }
  var rounded = Math.round(displayGramasi * 10) / 10;
  var title = '';
  if (calculated > 0 && Math.abs(calculated - Number(gramasiTotal)) > 0.01) {
    title = ' title="Tersimpan: ' + Number(gramasiTotal) + 'g, Terhitung: ' + Math.round(calculated * 10) / 10 + 'g" class="cursor-help"';
  }
  return '<span' + title + '>' + rounded + 'g</span>';
}

function renderSiklusBadges(usage) {
  if (!usage || !usage.length) return '<span class="text-stone-300">—</span>';
  var groups = {};
  usage.forEach(function(u) {
    if (!groups[u.siklus]) groups[u.siklus] = [];
    groups[u.siklus].push(u.hari);
  });
  return Object.keys(groups).map(function(s) {
    var label = 'H' + groups[s].join(', H');
    return '<span class="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold bg-sky-100 text-sky-700 border border-sky-200 mr-1 mb-0.5 whitespace-nowrap">' + escHtml(s) + ' ' + label + '</span>';
  }).join('');
}

function renderMenuHtml(menus) {
  return `<div class="flex flex-wrap justify-between gap-2 mb-4">
    <div class="flex flex-wrap items-center gap-2">
      <button id="add-menu-btn" class="h-11 px-5 bg-[#1e40af] hover:bg-[#1d4ed8] text-white rounded-xl text-sm font-semibold shadow-sm transition-all flex items-center gap-2">
        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
        Tambah Menu
      </button>
      <button id="menu-delete-selected" onclick="deleteSelectedMenu()" class="hidden h-10 px-4 text-sm font-medium text-red-600 bg-red-50 hover:bg-red-100 rounded-xl items-center gap-1.5 shadow-sm transition-all">
        Hapus Terpilih <span id="menu-selected-count" class="font-bold">0</span>
      </button>
    </div>
    <div class="flex gap-2">
      <button id="recalc-nutrisi-btn" onclick="recalcNutrisiMenu()" class="h-11 px-4 border border-stone-200 text-stone-700 hover:bg-stone-50 rounded-xl text-sm font-medium shadow-sm transition-all">Hitung Ulang Nutrisi</button>
      <div class="relative">
        <input type="text" id="search-menu-input" placeholder="Cari nama menu..." value="${menuState.search}"
          class="w-56 h-11 pl-10 pr-4 rounded-xl border border-stone-200 bg-white text-sm shadow-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all">
        <svg class="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-stone-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
        </svg>
      </div>
    </div>
  </div>
  <div class="bg-white border border-stone-200 rounded-2xl shadow-sm overflow-hidden">
    <div class="overflow-x-auto">
      <table class="w-full">
        <thead>
          <tr class="border-b border-stone-100">
            <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500 w-10">
              <input type="checkbox" id="menu-select-all" onchange="toggleSelectAllMenu(this)" class="cb-modern">
            </th>
            <th class="text-left px-3 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Siklus</th>
            <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Nama</th>
            <th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Kategori</th>
            <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Gramasi <span class="inline-flex items-center justify-center w-4 h-4 rounded-full bg-stone-200 text-stone-500 text-[9px] cursor-help font-bold" title="Gramasi total = jumlah seluruh bahan (g). 0 = belum ada bahan/ jumlah. Default terisi otomatis dari SP Referensi saat pilih bahan.">?</span></th>
            <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Kalori</th>
            <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Bahan</th>
            <th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Aksi</th>
          </tr>
        </thead>
        <tbody id="menu-table-body">
            ${menus.length > 0 ? menus.map((m) => `
            <tr class="border-b border-stone-50 hover:bg-stone-50/50 transition-colors">
              <td class="px-4 py-3 text-xs">
                <input type="checkbox" value="${m.id}" onchange="updateSelectedMenuCount()" class="menu-checkbox cb-modern">
              </td>
              <td class="px-3 py-3 text-xs">${renderSiklusBadges(m.siklus_usage)}</td>
              <td class="px-4 py-3 text-xs font-medium text-stone-700 truncate max-w-[180px]" title="${m.nama}">${m.nama}</td>
              <td class="px-4 py-3 text-xs whitespace-nowrap">${m.kategori_penerima ? kategoriBadge(m.kategori_penerima) : '-'}</td>
              <td class="px-4 py-3 text-xs text-right mono whitespace-nowrap text-stone-600">${renderGramasiCell(m.gramasi_total, m.bahan)}</td>
              <td class="px-4 py-3 text-xs text-right mono whitespace-nowrap text-stone-600">${m.kalori} kkal</td>
              <td class="px-4 py-3 text-xs text-left whitespace-nowrap">${renderBahanCell(m.bahan)}</td>
              <td class="px-4 py-3 text-xs text-right whitespace-nowrap">
                <button data-menu-id="${m.id}" class="edit-btn w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-blue-600 hover:bg-blue-50 transition-all" title="Edit"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
                <button data-menu-id="${m.id}" class="delete-btn w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-red-600 hover:bg-red-50 transition-all" title="Hapus"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>
              </td>
            </tr>`).join('') : '<tr><td colspan="8" class="text-center py-16 text-stone-400"><svg class="w-12 h-12 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M3 2v7c0 1.1.9 2 2 2h4a2 2 0 0 0 2-2V2"/><path d="M7 2v20"/><path d="M21 15V2v0a5 5 0 0 0-5 5v6c0 1.1.9 2 2 2h3Zm0 0v7"/></svg><div class="text-sm">Belum ada menu</div></td></tr>'}
        </tbody>
      </table>
    </div>
  </div>
  <div id="pagination-controls"></div>`;
}

function renderPagination() {
  const wrap = document.getElementById('pagination-controls');
  if (!wrap) return;
  if (menuState.totalPages <= 1) { wrap.innerHTML = ''; return; }
  var total = menuState.total;
  wrap.innerHTML = `<div class="flex items-center justify-between mt-3">
    <span class="text-sm text-stone-500">${total} data</span>
    <div class="flex gap-2">
      ${menuState.page > 1 ? '<button onclick="goToPage(' + (menuState.page - 1) + ')" class="px-3 py-1.5 text-sm font-medium rounded-lg border border-stone-200 hover:bg-stone-50 hover:border-stone-300 transition-all">Prev</button>' : ''}
      <span class="text-sm text-stone-500">Hal ${menuState.page} dari ${menuState.totalPages}</span>
      ${menuState.page < menuState.totalPages ? '<button onclick="goToPage(' + (menuState.page + 1) + ')" class="px-3 py-1.5 text-sm font-medium rounded-lg border border-stone-200 hover:bg-stone-50 hover:border-stone-300 transition-all">Next</button>' : ''}
    </div>
  </div>`;
}

function goToPage(page) {
  menuState.page = page;
  renderMenu();
}

function attachMenuHandlers() {
  const addBtn = document.getElementById('add-menu-btn');
  if (addBtn) addBtn.onclick = () => openMenuForm(null);
  const searchInput = document.getElementById('search-menu-input');
  if (searchInput) {
    let timer;
    searchInput.oninput = function() {
      clearTimeout(timer);
      timer = setTimeout(() => {
        menuState.search = this.value;
        menuState.page = 1;
        renderMenu();
      }, 300);
    };
  }
  document.querySelectorAll('.edit-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      const menuId = this.getAttribute('data-menu-id');
      editMenuById(menuId);
    });
  });
  document.querySelectorAll('.delete-btn').forEach(btn => {
    btn.addEventListener('click', function() {
      const menuId = this.getAttribute('data-menu-id');
      deleteMenu(menuId);
    });
  });
}

async function openMenuForm(editing) {
  await ensureBahanBakuLoaded();
  const m = editing || { nama: '', deskripsi: '', gramasi_total: 0, kalori: 0, protein: 0, karbohidrat: 0, lemak: 0, serat: 0, bahan: [] };
  document.getElementById('modal-title').innerHTML = (editing ? 'Edit Menu' : 'Menu Baru') + '<button onclick="event.stopPropagation();showMenuInfo()" class="ml-2 inline-flex items-center justify-center w-5 h-5 rounded-full bg-stone-100 hover:bg-blue-100 hover:text-blue-700 text-stone-400 transition-all" title="Info"><svg class="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg></button>';
  document.getElementById('modal-body').innerHTML = `
    <div>
      <label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Nama Menu *</label>
      <div class="flex gap-2 mt-1.5">
        <input id="m-nama" value="${m.nama}" class="flex-1 h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" />
        <button type="button" onclick="openSiklusMenuPicker()" class="shrink-0 px-4 h-11 text-xs font-semibold text-emerald-700 bg-emerald-50 border border-emerald-200 rounded-xl hover:bg-emerald-100 whitespace-nowrap transition-all shadow-sm" title="Ambil nama & bahan dari siklus">📋 Siklus</button>
      </div>
    </div>
    <div class="mt-3"><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Deskripsi</label><textarea id="m-deskripsi" rows="2" class="mt-1.5 w-full px-3 py-2 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all">${m.deskripsi || ''}</textarea></div>
    
    <input id="m-kalori" type="hidden" value="${m.kalori || 0}" />
    <input id="m-protein" type="hidden" value="${m.protein || 0}" />
    <input id="m-karbohidrat" type="hidden" value="${m.karbohidrat || 0}" />
    <input id="m-lemak" type="hidden" value="${m.lemak || 0}" />
    <input id="m-serat" type="hidden" value="${m.serat || 0}" />

    <div class="border-t border-stone-200 mt-4 pt-3">
      <div class="flex items-center justify-between gap-3 mb-2">
        <div class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Bahan</div>
        <div class="flex items-center gap-2">
          <button type="button" onclick="addBahanRow()" class="text-xs font-medium border border-stone-200 px-3 py-1.5 rounded-lg hover:bg-stone-50 shadow-sm transition-all">+ Tambah Bahan</button>
          <button type="button" onclick="saveCurrentMenuFromForm(); openMenuPoModal()" class="text-xs font-medium border border-emerald-300 text-emerald-700 hover:bg-emerald-50 px-3 py-1.5 rounded-lg shadow-sm transition-all flex items-center gap-1.5" title="Buat PO dari Menu">
            <svg class="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
            Buat PO
          </button>
        </div>
      </div>
      <div class="flex items-center gap-2 mb-2 text-xs text-stone-500">
        <span>Tampilkan total untuk</span>
        <input type="number" id="m-porsi" value="0" min="0" step="1" onchange="onPorsiChange()" placeholder="0" class="w-20 h-8 px-2 rounded-lg border border-stone-200 text-sm text-center mono focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" />
        <span>porsi</span>
        <span class="flex-1"></span>
        <button type="button" onclick="resetAllToSP()" class="text-xs font-medium border border-stone-200 px-2.5 py-1.5 rounded-lg hover:bg-stone-50 text-stone-500 shadow-sm transition-all">↺ Reset Semua ke SP</button>
      </div>
      <div id="bahan-list" class="space-y-2"></div>
    </div>
    `;
  window._editingMenuData = editing || null;
  window._menuBahan = (m.bahan || []).map(b => ({ bahan_baku_id: b.bahan_baku_id, nama: b.nama || '', jumlah: b.jumlah, satuan: b.satuan || 'g', kategori_sp: b.kategori_sp || '', berat_1_sp: b.berat_1_sp || 0, persen_bdd: b.persen_bdd || 100, berat_per_satuan: b.berat_per_satuan || 0, keterangan: b.keterangan || '' }));
  // Biarkan nilai tersimpan dari DB — user bisa klik "↺ Reset ke SP" jika ingin reset
  var savedPorsi = Number(m.jumlah_porsi) || 0;
  window._menuPorsi = savedPorsi;
  document.getElementById('m-porsi').value = savedPorsi;
  renderBahanList();
  hitungNutrisi();
  
  // Cek duplikat nama — load menu names once
  var existingNames = null;
  api.get('/menu?limit=500').then(function(resp) {
    existingNames = (resp.data || resp || []).filter(function(x) { return editing ? x.id !== editing.id : true; }).map(function(x) { return x.nama ? x.nama.toLowerCase().trim() : ''; });
  }).catch(function() { existingNames = []; });
  
  function checkDuplicateName(val) {
    var el = document.getElementById('m-nama');
    var dupEl = document.getElementById('m-nama-dup');
    var nama = (val || el.value).trim();
    if (!nama || !existingNames) { if (dupEl) dupEl.classList.add('hidden'); el.classList.remove('border-red-400','bg-red-50'); return false; }
    var isDup = existingNames.indexOf(nama.toLowerCase()) > -1;
    if (isDup) {
      el.classList.add('border-red-400','bg-red-50');
      if (!dupEl) {
        var p = document.createElement('p');
        p.id = 'm-nama-dup';
        p.className = 'text-xs text-red-600 mt-1';
        p.textContent = '⚠ Nama menu "' + nama + '" sudah ada';
        el.parentNode.appendChild(p);
      } else { dupEl.classList.remove('hidden'); dupEl.textContent = '⚠ Nama menu "' + nama + '" sudah ada'; }
    } else {
      el.classList.remove('border-red-400','bg-red-50');
      if (dupEl) dupEl.classList.add('hidden');
    }
    return isDup;
  }
  
  document.getElementById('m-nama').addEventListener('input', function() { checkDuplicateName(this.value); });
  
  document.getElementById('modal-save').onclick = async function() {
    try {
      if (!validateForm([{ id: 'm-nama', label: 'Nama Menu' }])) return;
      if (checkDuplicateName()) return showAlert('Nama menu sudah ada. Ganti nama terlebih dahulu.', 'warning');
      const payload = {
        nama: document.getElementById('m-nama').value,
        kategori_penerima: editing ? editing.kategori_penerima : null,
        deskripsi: document.getElementById('m-deskripsi').value,
        gramasi_total: Math.round((window._menuBahan || []).reduce(function(s,b){ return s + (Number(b.jumlah)||0); }, 0) * 100) / 100,
        kalori: +document.getElementById('m-kalori').value || 0,
        protein: +document.getElementById('m-protein').value || 0,
        karbohidrat: +document.getElementById('m-karbohidrat').value || 0,
        lemak: +document.getElementById('m-lemak').value || 0,
        serat: +document.getElementById('m-serat').value || 0,
        jumlah_porsi: Number(document.getElementById('m-porsi').value) || 0,
        bahan: window._menuBahan.filter(function(b) { return b.bahan_baku_id || b.nama; }),
      };
      if (editing) await api.put('/menu/' + editing.id, payload);
      else await api.post('/menu', payload);
      closeModal(); renderMenu();
    } catch (e) {
      showAlert('Gagal menyimpan: ' + (e.message || 'Unknown error'), 'error');
    }
  };
  document.getElementById('modal').classList.remove('hidden');
  document.getElementById('modal').classList.add('flex');
}
function addBahanRow() { window._menuBahan.push({ bahan_baku_id: '', jumlah: 0, satuan: 'g', nama: '', kategori_sp: '', berat_1_sp: 0, persen_bdd: 100, berat_per_satuan: 0, keterangan: '' }); renderBahanList(); }
function removeBahanRow(i) { window._menuBahan.splice(i, 1); renderBahanList(); hitungNutrisi(); }
function hitungNutrisi() {
  var totalKalori = 0, totalProtein = 0, totalKarbo = 0, totalLemak = 0, totalSerat = 0;
  (window._menuBahan || []).forEach(function(b) {
    var jml = +b.jumlah || 0;
    if (!jml) return;
    var ref = window._spRefMap && window._spRefMap[b.nama];
    if (ref) {
      totalKalori += jml / 100 * (ref.energi || 0);
      totalProtein += jml / 100 * (ref.protein || 0);
      totalKarbo += jml / 100 * (ref.karbohidrat || 0);
      totalLemak += jml / 100 * (ref.lemak || 0);
      totalSerat += jml / 100 * (ref.serat || 0);
    } else {
      totalKalori += jml / 100 * (b.kalori || 0);
      totalProtein += jml / 100 * (b.protein || 0);
      totalKarbo += jml / 100 * (b.karbohidrat || 0);
      totalLemak += jml / 100 * (b.lemak || 0);
      totalSerat += jml / 100 * (b.serat || 0);
    }
  });
  ['kalori','protein','karbohidrat','lemak','serat'].forEach(function(k) {
    var el = document.getElementById('m-' + k);
    if (el) el.value = Math.round(({kalori:totalKalori,protein:totalProtein,karbohidrat:totalKarbo,lemak:totalLemak,serat:totalSerat})[k] * 100) / 100;
  });
}

function updateBahan(i, k, v) {
  if (k === 'jumlah') {
    var b = window._menuBahan[i];
    if (!b) return;
    var porsi = Number(window._menuPorsi) || 1;
    var perUnit = Number(b.berat_per_satuan) || Number(b.berat_1_sp) || 1;
    // Input shows total when porsi>0; convert back to grams per-porsi for storage
    var valPerPorsi = Number(v) / porsi;
    var newJumlah;
    if (perUnit > 0 && (b.satuan === 'Kg' || ['Pcs','Butir','Botol','Ikat','Renceng','Karton'].includes(b.satuan))) {
      newJumlah = valPerPorsi * perUnit;
    } else {
      newJumlah = valPerPorsi;
    }
    // Warning jika nilai terlalu jauh dari SP default (> 10x)
    var sp = window._spRefMap && window._spRefMap[b.nama];
    var defaultGram = (sp ? Number(sp.berat_bersih) : 0) || Number(b.berat_1_sp) || 0;
    if (defaultGram > 0 && newJumlah > defaultGram * 10) {
      var spDisplay = defaultGram / perUnit;
      showConfirm('Nilai ' + v + ' ' + b.satuan + ' jauh dari standar SP (' + Math.round(spDisplay * 100) / 100 + ' ' + b.satuan + '). Lanjutkan?', 'Lanjutkan', 'Batalkan', '', 'question').then(function(ok) {
        if (ok) {
          b.jumlah = newJumlah;
          delete b._autoJumlah;
          hitungNutrisi();
          renderBahanList();
        } else {
          renderBahanList();
        }
      });
      return;
    }
    b.jumlah = newJumlah;
    delete b._autoJumlah;
  } else {
    window._menuBahan[i][k] = v;
  }
  hitungNutrisi();
  renderBahanList();
}
function resetAllToSP() {
  (window._menuBahan || []).forEach(function(b, i) {
    resetBahanToSP(i);
  });
}
function resetBahanToSP(i) {
  var b = window._menuBahan[i];
  if (!b) return;
  var sp = window._spRefMap && window._spRefMap[b.nama];
  var defaultGram = (sp ? Number(sp.berat_bersih) : 0) || Number(b.berat_1_sp) || 0;
  if (!defaultGram) return;
  b.jumlah = defaultGram;
  delete b._autoJumlah;
  hitungNutrisi();
  renderBahanList();
}
function renderBahanList() {
  var porsi = Number(window._menuPorsi) || 0;
  document.getElementById('bahan-list').innerHTML = window._menuBahan.map((b, i) => {
    var displayNama = b.nama || '';
    var displaySatuan = b.satuan || 'g';
      var perUnit = Number(b.berat_per_satuan) || Number(b.berat_1_sp) || 1;
      var displayJumlah = b.jumlah || 0;
      if (perUnit > 0 && (displaySatuan === 'Kg' || ['Pcs','Butir','Botol','Ikat','Renceng','Karton'].includes(displaySatuan))) {
        displayJumlah = displayJumlah / perUnit;
      }
      var totalJumlah = porsi > 0 ? displayJumlah * porsi : 0;
      var inputStep = displaySatuan === 'Kg' ? '0.01' : (['Pcs','Butir','Botol','Ikat','Renceng','Karton'].includes(displaySatuan) ? '1' : '0.01');
      var inputValue = porsi > 0 ? (totalJumlah ? Math.round(totalJumlah * 100) / 100 : '0') : (displayJumlah ? Math.round(displayJumlah * 100) / 100 : '0');
      var inputTitle = porsi > 0 ? 'Total untuk ' + porsi + ' porsi (' + displaySatuan + ')' : (displaySatuan === 'g' ? 'Gram per porsi' : 'Jumlah per porsi (' + displaySatuan + ')');
      return '<div class="mb-1.5">' +
        '<div class="grid grid-cols-12 gap-1.5 items-center">' +
          '<div class="col-span-4 relative">' +
            '<input id="b-input-' + i + '" autocomplete="off" value="' + displayNama + '" placeholder="Cari bahan..." oninput="onBahanSearch(' + i + ', this)" onfocus="onBahanSearch(' + i + ', this)" onblur="setTimeout(function(){closeBahanDropdown(' + i + ')},200)" class="w-full h-10 px-3 border border-stone-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" />' +
            '<div id="b-drop-' + i + '" class="hidden absolute z-10 w-full mt-0.5 bg-white border border-stone-200 rounded-lg shadow-lg max-h-48 overflow-y-auto text-sm"></div>' +
          '</div>' +
          '<div class="col-span-3 flex">' +
            '<input type="number" step="' + inputStep + '" value="' + inputValue + '" onchange="updateBahan(' + i + ', \'jumlah\', this.value)" class="flex-1 min-w-0 h-10 px-3 border border-stone-200 rounded-l-lg text-sm mono focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" title="' + inputTitle + '" />' +
            '<span class="inline-flex items-center px-2.5 h-10 text-xs font-semibold bg-stone-100 text-stone-600 border border-l-0 border-stone-200 rounded-r-lg whitespace-nowrap">' + displaySatuan + '</span>' +
          '</div>' +
          '<div class="col-span-4">' +
            '<input type="text" value="' + (b.keterangan || '') + '" onchange="updateBahan(' + i + ', \'keterangan\', this.value)" placeholder="catatan" class="w-full h-10 px-3 border border-stone-200 rounded-lg text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" />' +
          '</div>' +
          '<button type="button" onclick="removeBahanRow(' + i + ')" class="col-span-1 inline-flex items-center justify-center h-10 w-full text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all" title="Hapus bahan"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>' +
        '</div>' +
      '</div>';
  }).join('');
}

function onPorsiChange() {
  window._menuPorsi = Number(document.getElementById('m-porsi').value) || 0;
  renderBahanList();
}
function onBahanSearch(i, el) {
  var val = el.value;
  var dropdown = document.getElementById('b-drop-' + i);
  if (!dropdown) return;
  // Cek exact match di sp_referensi_bahan (prioritas)
  if (window._spRefMap && window._spRefMap[val]) {
    selectBahan(i, val);
    dropdown.classList.add('hidden');
    return;
  }
  // Cek exact match di bahan_baku (fallback)
  var bbExact = (window._bahanBaku || []).find(function(b) { return b.nama && b.nama.toLowerCase() === val.toLowerCase().trim(); });
  if (bbExact) {
    selectBahan(i, val);
    dropdown.classList.add('hidden');
    return;
  }
  var q = val.toLowerCase().trim();
  if (!q) { dropdown.classList.add('hidden'); return; }
  // Gabungkan hasil dari sp_referensi_bahan dan bahan_baku
  var spMatches = (window._spRefList || []).filter(function(r) { return r.nama && r.nama.toLowerCase().includes(q); });
  var bbMatches = (window._bahanBaku || []).filter(function(b) { return b.nama && b.nama.toLowerCase().includes(q); });
  // Merge: prioritaskan sp_referensi, tambah bahan_baku yang belum tercakup
  var seen = new Set();
  var merged = [];
  for (var r of spMatches) {
    if (!seen.has(r.nama.toLowerCase())) {
      seen.add(r.nama.toLowerCase());
      var bbSat = (window._bahanBaku || []).find(function(bb) { return bb.nama && bb.nama.toLowerCase() === r.nama.toLowerCase(); });
      merged.push({ sumber: 'sp', nama: r.nama, kategori: r.kategori || '', berat: r.berat_bersih, satuan: bbSat ? bbSat.satuan : 'g', berat_per_satuan: bbSat ? Number(bbSat.berat_per_satuan) : 0, nutrisi: (r.energi ? r.energi + ' kkal' : '') + (r.protein ? ' · P' + r.protein + 'g' : '') + (r.karbohidrat ? ' · KH' + r.karbohidrat + 'g' : '') });
    }
  }
  for (var b of bbMatches) {
    if (!seen.has(b.nama.toLowerCase())) {
      seen.add(b.nama.toLowerCase());
      merged.push({ sumber: 'bb', nama: b.nama, kategori: b.kategori_sp || '', berat: b.berat_1_sp, satuan: b.satuan || 'g', berat_per_satuan: Number(b.berat_per_satuan) || 0, nutrisi: (b.kalori ? b.kalori + ' kkal' : '') + (b.protein ? ' · P' + b.protein + 'g' : '') + (b.karbohidrat ? ' · KH' + b.karbohidrat + 'g' : '') });
    }
  }
  if (!merged.length) { dropdown.classList.add('hidden'); return; }
  dropdown.innerHTML = merged.map(function(item) {
    var badge = item.sumber === 'sp' ? '<span class="text-[9px] bg-blue-100 text-blue-700 px-1 py-0.5 rounded mr-1">SP</span>' : '<span class="text-[9px] bg-amber-100 text-amber-700 px-1 py-0.5 rounded mr-1">Baku</span>';
    var satuanInfo = '';
    if (item.satuan && item.satuan.toLowerCase() !== 'g' && item.satuan.toLowerCase() !== 'gram') {
      satuanInfo = ' · Satuan: <span class="font-medium">' + item.satuan + '</span>';
    }
    return '<div onclick="selectBahan(' + i + ", '" + item.nama.replace(/'/g, "\\'") + "')\" class=\"px-3 py-2 hover:bg-blue-50 cursor-pointer border-b border-stone-100 last:border-0\">" +
      '<div class="font-medium text-stone-800">' + badge + ' ' + item.nama + '</div>' +
      '<div class="text-[10px] text-stone-400">' + (item.kategori || '') + (item.berat ? ' · 1SP=' + item.berat + 'g' : '') + satuanInfo + (item.nutrisi ? ' · ' + item.nutrisi : '') + '</div>' +
    '</div>';
  }).join('');
  dropdown.classList.remove('hidden');
}

function closeBahanDropdown(i) {
  var d = document.getElementById('b-drop-' + i);
  if (d) d.classList.add('hidden');
}

async function selectBahan(i, nama) {
  var ref = window._spRefMap && window._spRefMap[nama];
  var bb = (window._bahanBaku || []).find(function(b) { return b.nama.toLowerCase() === nama.toLowerCase(); });
  
  if (ref) {
    // DATA DARI SP REFERENSI
    var spItem = (window._spRefList || []).find(function(r) { return r.nama === nama; });
    var kat = spItem ? spItem.kategori : (bb ? bb.kategori_sp : '');
    var berat1Sp = ref.berat_bersih;
    var perPorsi = berat1Sp;
    
    if (!bb) {
      // Auto-create bahan_baku jika belum ada di master
      try {
        var created = await api.post('/bahan_baku', {
          nama: nama,
          satuan: 'g',
          kategori_sp: kat || '',
          berat_1_sp: berat1Sp,
          persen_bdd: Math.round(ref.bdd_persen * 100),
          berat_per_satuan: berat1Sp,
          kalori: ref.energi || 0,
          protein: ref.protein || 0,
          karbohidrat: ref.karbohidrat || 0,
          lemak: ref.lemak || 0,
          serat: ref.serat || 0,
        });
        window._bahanBaku.push(created);
        bb = created;
      } catch (e) {
        console.warn('Gagal auto-create bahan_baku:', e.message);
      }
    }
    
    window._menuBahan[i].bahan_baku_id = bb ? bb.id : '';
    window._menuBahan[i].nama = nama;
    window._menuBahan[i].berat_per_satuan = Number(bb ? bb.berat_per_satuan : 0) || berat1Sp;
    window._menuBahan[i].satuan = bb ? (bb.satuan || 'g') : 'g';
    window._menuBahan[i].kategori_sp = kat;
    window._menuBahan[i].berat_1_sp = berat1Sp;
    window._menuBahan[i].persen_bdd = Math.round(ref.bdd_persen * 100);
    window._menuBahan[i].kalori = ref.energi || 0;
    window._menuBahan[i].protein = ref.protein || 0;
    window._menuBahan[i].karbohidrat = ref.karbohidrat || 0;
    window._menuBahan[i].lemak = ref.lemak || 0;
    window._menuBahan[i].serat = ref.serat || 0;
    window._menuBahan[i].jumlah = perPorsi;
    window._menuBahan[i]._autoJumlah = perPorsi;
  } else if (bb) {
    // FALLBACK: DATA DARI BAHAN BAKU (tanpa SP reference)
    var kat = bb.kategori_sp || '';
    var berat1Sp = Number(bb.berat_1_sp || 0);
    var perPorsi = berat1Sp; // Default: 1 SP = berat_1_sp gram
    
    window._menuBahan[i].bahan_baku_id = bb.id || '';
    window._menuBahan[i].nama = nama;
    window._menuBahan[i].berat_per_satuan = Number(bb.berat_per_satuan) || 0;
    window._menuBahan[i].satuan = bb.satuan || 'g';
    window._menuBahan[i].kategori_sp = kat;
    window._menuBahan[i].berat_1_sp = berat1Sp;
    window._menuBahan[i].persen_bdd = Number(bb.persen_bdd || 100);
    window._menuBahan[i].kalori = Number(bb.kalori || 0);
    window._menuBahan[i].protein = Number(bb.protein || 0);
    window._menuBahan[i].karbohidrat = Number(bb.karbohidrat || 0);
    window._menuBahan[i].lemak = Number(bb.lemak || 0);
    window._menuBahan[i].serat = Number(bb.serat || 0);
    window._menuBahan[i].jumlah = perPorsi;
    window._menuBahan[i]._autoJumlah = perPorsi;
  } else {
    // Tidak ditemukan di sp_referensi maupun bahan_baku
    console.warn('Bahan tidak ditemukan:', nama);
    return;
  }
  
  var input = document.getElementById('b-input-' + i);
  if (input) input.value = nama;
  renderBahanList();
  hitungNutrisi();
}

async function deleteMenu(id) { if (!await showConfirm('Hapus menu?')) return; await api.del('/menu/' + id); renderMenu(); }

function toggleSelectAllMenu(master) {
  document.querySelectorAll('.menu-checkbox').forEach(cb => cb.checked = master.checked);
  updateSelectedMenuCount();
}
function updateSelectedMenuCount() {
  var checked = document.querySelectorAll('.menu-checkbox:checked').length;
  var btn = document.getElementById('menu-delete-selected');
  var countEl = document.getElementById('menu-selected-count');
  if (!btn || !countEl) return;
  if (checked > 0) {
    btn.classList.remove('hidden');
    btn.classList.add('inline-flex');
    countEl.textContent = checked;
  } else {
    btn.classList.add('hidden');
    btn.classList.remove('inline-flex');
  }
}
async function deleteSelectedMenu() {
  var checked = document.querySelectorAll('.menu-checkbox:checked');
  var ids = Array.from(checked).map(cb => parseInt(cb.value)).filter(id => !isNaN(id));
  if (!ids.length) return showAlert('Pilih menu yang akan dihapus', 'warning');
  if (!await showConfirm('Hapus ' + ids.length + ' menu terpilih?')) return;
  try {
    await api.post('/menu/bulk-delete', { ids });
    showToast(ids.length + ' menu berhasil dihapus', 'success');
    renderMenu();
  } catch (e) {
    showToast('Gagal menghapus: ' + (e.message || 'Unknown error'), 'error');
  }
}

async function recalcNutrisiMenu() {
  if (!await showConfirm('Hitung ulang nutrisi semua menu berdasarkan bahan baku terkini?', 'Ya, Hitung')) return;
  try {
    var res = await api.post('/menu/recalculate-nutrisi', {});
    showToast(res.recalculated + ' menu diperbarui dari ' + res.total, 'success');
    renderMenu();
  } catch (e) {
    showAlert(e.message || 'Gagal', 'error');
  }
}

function escHtml(s) {
  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
}

function closeSiklusMenuPicker() {
  var m = document.getElementById('siklus-menu-picker');
  if (m) m.remove();
}

async function openSiklusMenuPicker() {
  try {
    var data = await api.get('/siklus/recipe-names');
    var hasNames = data.some(function(s) { return s.names && s.names.length; });
    if (!data.length || !hasNames) {
      showAlert('Belum ada siklus dengan nama menu atau resep. Buat siklus terlebih dahulu.', 'warning');
      return;
    }

    var html = '<div class="p-4 space-y-3 max-h-[420px] overflow-y-auto">';
    for (var si = 0; si < data.length; si++) {
      var s = data[si];
      if (!s.names || !s.names.length) continue;
      var statusColor = s.status === 'Aktif' ? 'bg-emerald-100 text-emerald-800' : s.status === 'Draft' ? 'bg-amber-100 text-amber-800' : 'bg-stone-100 text-stone-600';
      html += '<div class="border border-stone-200 rounded-xl overflow-hidden">' +
        '<div class="px-4 py-2.5 bg-stone-50 border-b border-stone-200 flex items-center justify-between">' +
        '<div class="font-semibold text-sm text-stone-700">' + escHtml(s.nama) + '</div>' +
            '<div class="flex items-center gap-2">' +
            (s.jumlah_porsi ? '<span class="text-[10px] text-stone-400">' + s.jumlah_porsi + ' porsi</span>' : '') +
            '<span class="text-[10px] px-2 py-0.5 rounded-full font-medium ' + statusColor + ' capitalize">' + s.status + '</span>' +
          '</div>' +
        '</div>' +
        '<div class="divide-y divide-stone-100">';
      for (var ni = 0; ni < s.names.length; ni++) {
        var n = s.names[ni];
        if (n.source === 'menu') {
          // Menu items — clickable, untuk import bahan
          var bahanJson = escHtml(JSON.stringify(n.bahan || []));
    html += '<button type="button" onclick="selectSiklusMenuName(\'' + escHtml(n.nama) + "', '" + bahanJson + "', " + (Number(s.jumlah_porsi) || 0) + ")\" class=\"w-full text-left px-4 py-2 hover:bg-blue-50 transition-colors\">" +
            '<div class="flex items-center gap-2">' +
            '<span class="text-xs text-stone-400 shrink-0 w-8">H' + n.hari_ke + '</span>' +
            '<span class="text-xs text-stone-500 shrink-0 w-14">' + n.hari_nama + '</span>' +
            '<span class="text-[10px] px-1.5 py-0.5 rounded font-medium bg-blue-100 text-blue-700 shrink-0">Menu</span>' +
            '<span class="text-sm font-medium text-stone-800 truncate">' + escHtml(n.nama) + '</span>' +
            (n.bahan && n.bahan.length ? '<span class="text-[10px] text-stone-400 shrink-0">' + n.bahan.length + ' bahan</span>' : '') +
            '<svg class="w-4 h-4 text-stone-300 shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"/></svg>' +
            '</div>' +
          '</button>';
        } else {
          // Resep items — non-clickable, info saja
          html += '<div class="px-4 py-2">' +
            '<div class="flex items-center gap-2 text-stone-500">' +
            '<span class="text-xs shrink-0 w-8">H' + n.hari_ke + '</span>' +
            '<span class="text-xs shrink-0 w-14">' + n.hari_nama + '</span>' +
            '<span class="text-[10px] px-1.5 py-0.5 rounded font-medium bg-stone-100 text-stone-500 shrink-0">Resep</span>' +
            '<span class="text-sm font-medium text-stone-500 truncate">' + escHtml(n.nama) + '</span>' +
            (n.kategori_sp ? '<span class="text-[10px] text-stone-400 shrink-0 hidden sm:inline">(' + escHtml(n.kategori_sp) + ')</span>' : '') +
            (n.bahan && n.bahan.length ? '<span class="text-[10px] text-stone-400 shrink-0">· ' + escHtml(n.bahan[0].nama) + '</span>' : '') +
            '</div>' +
          '</div>';
        }
      }
      html += '</div></div>';
    }
    html += '</div>';

    // Create floating modal on top of main modal
    var existing = document.getElementById('siklus-menu-picker');
    if (existing) existing.remove();
    var m = document.createElement('div');
    m.id = 'siklus-menu-picker';
    m.className = 'fixed inset-0 z-[60] flex items-center justify-center bg-black/40';
    m.innerHTML = '<div class="bg-white rounded-2xl shadow-xl max-w-lg w-full mx-4 max-h-[90vh] overflow-hidden">' +
      '<div class="flex items-center justify-between px-5 py-3 border-b border-stone-200">' +
        '<h3 class="font-bold text-stone-700 text-sm">Pilih Nama dari Siklus Menu</h3>' +
        '<button onclick="closeSiklusMenuPicker()" class="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-stone-100 text-stone-400">&times;</button>' +
      '</div>' +
      '<div id="sk-picker-body">' + html + '</div>' +
    '</div>';
    document.body.appendChild(m);
    m.addEventListener('click', function(e) { if (e.target === m) closeSiklusMenuPicker(); });
  } catch (e) {
    showAlert('Gagal memuat data siklus: ' + e.message, 'error');
  }
}
async function selectSiklusMenuName(nama, bahanJson, siklusPorsi) {
  document.getElementById('m-nama').value = nama;
  
  // Auto-fill jumlah porsi jika > 0
  if (siklusPorsi > 0) {
    document.getElementById('m-porsi').value = siklusPorsi;
    window._menuPorsi = siklusPorsi;
  }
  
  // Load bahan dari siklus
  var bahan = [];
  try { bahan = JSON.parse(bahanJson || '[]'); } catch(e) { bahan = []; }
  
  // Konfirmasi jika sudah ada bahan di form
  if (bahan.length && window._menuBahan.some(function(b) { return b.nama; })) {
    if (!await showConfirm('Akan mengganti ' + window._menuBahan.filter(function(b){return b.nama;}).length + ' bahan yang sudah ada dengan ' + bahan.length + ' bahan dari siklus. Lanjutkan?')) {
      return;
    }
  }
  
  if (bahan.length) {
    window._menuBahan = [];
    for (var i = 0; i < bahan.length; i++) {
      if (!bahan[i].nama) continue;
      window._menuBahan.push({ bahan_baku_id: '', jumlah: 0, satuan: 'g', nama: '', keterangan: '' });
      await selectBahan(window._menuBahan.length - 1, bahan[i].nama);
    }
    showToast('Nama & ' + bahan.length + ' bahan diambil dari siklus', 'success');
  } else {
    showToast('Nama diambil dari siklus: ' + nama, 'success');
  }
  
  renderBahanList();
  closeSiklusMenuPicker();
}

