let karyawanOptions = [];
async function loadKaryawanOptions() {
  try {
    const rows = await api.get('/karyawan?status=Aktif');
    karyawanOptions = Array.isArray(rows) ? rows : [];
    const opts = '<option value="">Semua Karyawan</option>' +
      karyawanOptions.map(k => `<option value="${k.id}">${k.nama} - ${k.jabatan_nama || '-'}</option>`).join('');
    const paySel = document.getElementById('pay-filter-karyawan');
    if (paySel) paySel.innerHTML = opts;
    const absSel = document.getElementById('abs-filter-karyawan');
    if (absSel) absSel.innerHTML = opts;
    const absFormSel = document.getElementById('absensi-karyawan');
    if (absFormSel) absFormSel.innerHTML = '<option value="">— Pilih —</option>' +
      karyawanOptions.map(k => `<option value="${k.id}">${k.nama} - ${k.jabatan_nama || '-'}</option>`).join('');
  } catch (e) {
    console.error('loadKaryawanOptions error:', e);
    karyawanOptions = [];
  }
}
async function loadAbsensi(page = 1) {
  const params = new URLSearchParams();
  const fk = document.getElementById('abs-filter-karyawan').value;
  const fta = document.getElementById('abs-filter-tanggal-awal').value;
  const ftb = document.getElementById('abs-filter-tanggal-akhir').value;
  const fs = document.getElementById('abs-filter-status').value;
  if (fk) params.set('karyawan_id', fk);
  if (fta) params.set('tanggal_awal', fta);
  if (ftb) params.set('tanggal_akhir', ftb);
  if (fs) params.set('status', fs);
  params.set('page', page);
  const res = await api.get('/absensi?' + params);
  renderAbsensiTable(res.data, res);
}
function openFoto(src) {
  window.open(src, '_blank');
}

function renderAbsensiTable(list, pagination) {
  const tb = document.querySelector('#absensi-modal').parentElement.querySelector('tbody');
  function fotoCell(val) {
    if (!val) return '<span class="text-stone-300 text-[10px]">—</span>';
    const s = val.replace(/"/g,'&quot;');
    return '<img src="'+s+'" onclick="openFoto(\''+s+'\')" class="w-9 h-9 rounded-lg object-cover cursor-pointer border border-stone-200 hover:border-blue-400 hover:shadow-md transition-all" title="Klik untuk lihat penuh">';
  }
  if (!list.length) { tb.innerHTML = '<tr><td colspan="10" class="text-center py-12 text-stone-400"><svg class="w-14 h-14 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg><div>Belum ada data absensi</div></td></tr>'; } else {
    tb.innerHTML = list.map(a => `
      <tr class="border-t border-stone-100">
        <td class="px-4 py-3 text-sm whitespace-nowrap">${fmtDate(a.tanggal)}</td>
        <td class="px-4 py-3 text-sm font-medium">${a.nama_karyawan}</td>
        <td class="px-4 py-3 text-sm">${a.jabatan || '-'}</td>
        <td class="px-4 py-3 text-sm text-center"><span class="badge ${a.status==='Hadir'?'badge-hadir':a.status==='Sakit'?'badge-sakit':a.status==='Izin'?'badge-izin':a.status==='Cuti'?'badge-cuti':a.status==='Alpha'?'badge-alpha':a.status==='Terlambat'?'badge-terlambat':'badge-hadir'}">${a.status}</span></td>
        <td class="px-4 py-3 text-sm text-center mono">${a.jam_masuk || '-'}</td>
        <td class="px-4 py-3 text-sm text-center mono">${a.jam_keluar || '-'}</td>
        <td class="px-4 py-3 text-sm text-center">${fotoCell(a.foto_masuk)}</td>
        <td class="px-4 py-3 text-sm text-center">${fotoCell(a.foto_keluar)}</td>
        <td class="px-4 py-3 text-sm">${a.keterangan || '-'}</td>
        <td class="px-4 py-3 text-sm text-right whitespace-nowrap">
          <button data-id="${a.id}" class="edit-absensi text-stone-500 hover:text-stone-900 mr-2" title="Edit"><svg class="w-4 h-4 inline" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button>
          <button data-id="${a.id}" class="delete-absensi text-red-600 hover:text-red-800" title="Hapus"><svg class="w-4 h-4 inline" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button>
        </td>
      </tr>`).join('');
    tb.querySelectorAll('.edit-absensi').forEach(b => b.onclick = () => openAbsensiForm(list.find(x => x.id == b.dataset.id)));
    tb.querySelectorAll('.delete-absensi').forEach(b => b.onclick = async () => {
      if (!await showConfirm('Hapus data absensi?')) return;
      await api.del('/absensi/' + b.dataset.id);
      loadAbsensi(pagination?.page || 1);
    });
  }
  const pg = document.getElementById('absensi-pagination');
  if (pg && pagination) {
    pg.innerHTML = `<span>${pagination.total} data</span><div class="flex gap-1">${pagination.totalPages > 1 ? Array.from({ length: pagination.totalPages }, (_, i) => `<button onclick="loadAbsensi(${i + 1})" class="px-3 py-1 rounded ${i + 1 === pagination.page ? 'bg-[#1e40af] text-white' : 'bg-stone-100 hover:bg-stone-200'}">${i + 1}</button>`).join('') : ''}</div>`;
  }
}
function formatDateInput(val) {
  // HTML input[type=date] butuh format YYYY-MM-DD dalam TIMEZONE LOKAL
  // Database return ISO string UTC: "2026-07-12T17:00:00.000Z" (sebenarnya 13 Juli WIB)
  // Pakai slice(0,10) SALAH karena ambil tanggal UTC, bukan lokal
  if (!val) return '';
  const d = new Date(val);
  if (!isNaN(d.getTime())) {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  }
  // Fallback: ambil 10 karakter pertama
  return val.slice(0, 10);
}

function openAbsensiForm(a) {
  document.getElementById('absensi-id').value = a ? a.id : '';
  document.getElementById('absensi-tanggal').value = a ? formatDateInput(a.tanggal) : new Date().toISOString().slice(0,10);
  document.getElementById('absensi-status').value = a ? a.status : 'Hadir';
  document.getElementById('absensi-masuk').value = a ? a.jam_masuk || '' : '';
  document.getElementById('absensi-keluar').value = a ? a.jam_keluar || '' : '';
  document.getElementById('absensi-keterangan').value = a ? a.keterangan || '' : '';
  document.getElementById('absensi-modal-title').textContent = a ? 'Edit Absensi' : 'Input Absensi';

  // Populate dropdown karyawan dulu, BARU set value (biar selection-nya tidak hilang)
  const sel = document.getElementById('absensi-karyawan');
  // Pakai karyawanOptions dari modul penggajian, fallback ke window.karyawanOptions
  // (di-set oleh renderAbsensi di absensi.js)
  const options = (typeof karyawanOptions !== 'undefined' && karyawanOptions.length)
    ? karyawanOptions
    : (window.karyawanOptions || []);
  sel.innerHTML = '<option value="">— Pilih —</option>' +
    options.map(k => `<option value="${k.id}">${k.nama} - ${k.jabatan_nama || '-'}</option>`).join('');
  
  // Set value setelah options tersedia
  if (a && a.karyawan_id) {
    sel.value = a.karyawan_id;
  }

  document.getElementById('absensi-modal').classList.remove('hidden');
  document.getElementById('absensi-modal').classList.add('flex');
}
async function saveAbsensi() {
  const id = document.getElementById('absensi-id').value;
  const tanggal = document.getElementById('absensi-tanggal').value;
  const payload = {
    karyawan_id: +(document.getElementById('absensi-karyawan').value || 0),
    tanggal: tanggal,
    status: document.getElementById('absensi-status').value,
    jam_masuk: document.getElementById('absensi-masuk').value,
    jam_keluar: document.getElementById('absensi-keluar').value,
    keterangan: document.getElementById('absensi-keterangan').value,
  };
  if (!validateForm([{ id: 'absensi-karyawan', label: 'Karyawan', type: 'select' }, { id: 'absensi-tanggal', label: 'Tanggal' }])) return;

  // Cek hari libur
  try {
    const cek = await api.get('/hari-libur/cek?tanggal=' + tanggal);
    if (cek && cek.libur) {
      showAlert('Tidak bisa input/edit absensi: ' + tanggal + ' adalah hari libur (' + cek.data.nama + ')', 'error');
      return;
    }
  } catch (e) { /* skip if endpoint not ready */ }

  try {
    if (id) {
      await api.put('/absensi/' + id, payload);
    } else {
      await api.post('/absensi', payload);
    }
    document.getElementById('absensi-modal').classList.add('hidden');
    document.getElementById('absensi-modal').classList.remove('flex');
    loadAbsensi();
  } catch (err) {
    var msg = err.error || err.message || 'Gagal simpan';
    if (err.libur) {
      showAlert('Tidak bisa input/edit absensi: tanggal ini adalah hari libur (' + (err.nama_libur || '') + ')', 'error');
    } else {
      showAlert(msg, 'error');
    }
  }
}

// ===== Payroll Helpers =====
let payrollListGlobal = [];
async function loadPayroll() {
  const params = new URLSearchParams();
  const fk = document.getElementById('pay-filter-karyawan').value;
  const fp = document.getElementById('pay-filter-periode').value;
  const fs = document.getElementById('pay-filter-status').value;
  if (fk) params.set('karyawan_id', fk);
  if (fp) { const [tahun, bulan] = fp.split('-'); params.set('tahun', tahun); params.set('bulan', String(parseInt(bulan))); }
  if (fs) params.set('status', fs);
  payrollListGlobal = await api.get('/payroll?' + params);
  renderPayrollTable(payrollListGlobal);
}
function renderPayrollTable(list) {
  const tb = document.querySelector('#payroll-modal').parentElement.querySelector('tbody');
  if (!list.length) { tb.innerHTML = '<tr><td colspan="9" class="text-center py-12 text-stone-400"><svg class="w-14 h-14 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg><div>Belum ada data payroll</div></td></tr>'; return; }
  const BLN = ['','Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
  tb.innerHTML = list.map(p => `
    <tr class="border-t border-stone-100">
      <td class="px-4 py-3 text-sm whitespace-nowrap">${BLN[p.bulan]} ${p.tahun}</td>
      <td class="px-4 py-3 text-sm font-medium">${p.nama_karyawan}</td>
      <td class="px-4 py-3 text-sm">${p.jabatan || '-'}</td>
      <td class="px-4 py-3 text-sm text-right mono">${fmtIDR(p.gaji_pokok)}</td>
      <td class="px-4 py-3 text-sm text-right mono">${fmtIDR(p.tunjangan)}</td>
      <td class="px-4 py-3 text-sm text-right mono">${fmtIDR(p.potongan)}</td>
      <td class="px-4 py-3 text-sm text-right mono font-medium">${fmtIDR(p.total_gaji)}</td>
      <td class="px-4 py-3 text-sm text-center">${p.status}</td>
      <td class="px-4 py-3 text-sm text-right whitespace-nowrap">
        <button data-id="${p.id}" class="edit-payroll text-stone-500 hover:text-stone-900 mr-2">Edit</button>
        <button data-id="${p.id}" class="text-red-600">Hapus</button>
      </td>
    </tr>`).join('');
  tb.querySelectorAll('.edit-payroll').forEach(b => b.onclick = () => openPayrollForm(payrollListGlobal.find(x => x.id == b.dataset.id)));
  tb.querySelectorAll('.text-red-600').forEach(b => b.onclick = async () => {
    if (!await showConfirm('Hapus data payroll?')) return;
    await api.del('/payroll/' + b.dataset.id);
    loadPayroll();
  });
}
function openPayrollForm(p) {
  document.getElementById('payroll-id').value = p ? p.id : '';
  document.getElementById('payroll-karyawan').value = p ? p.karyawan_id : '';
  const now = new Date();
  const tahun = p ? p.tahun : now.getFullYear();
  const bulan = p ? String(p.bulan).padStart(2, '0') : String(now.getMonth() + 1).padStart(2, '0');
  document.getElementById('payroll-periode').value = tahun + '-' + bulan + '-01';
  document.getElementById('payroll-gaji').value = p ? p.gaji_pokok : '';
  document.getElementById('payroll-tunjangan').value = p ? p.tunjangan : '';
  document.getElementById('payroll-potongan').value = p ? p.potongan : '';
  document.getElementById('payroll-status').value = p ? p.status : 'Draft';
  document.getElementById('payroll-modal-title').textContent = p ? 'Edit Payroll' : 'Tambah Payroll';
  const sel = document.getElementById('payroll-karyawan');
  sel.innerHTML = (karyawanOptions || []).map(k => `<option value="${k.id}">${k.nama} - ${k.jabatan_nama || '-'}</option>`).join('');
  document.getElementById('payroll-modal').classList.remove('hidden');
  document.getElementById('payroll-modal').classList.add('flex');
}
function savePayroll() {
  const id = document.getElementById('payroll-id').value;
  const periode = document.getElementById('payroll-periode').value;
  const [thn, bln] = periode ? periode.split('-') : [];
  const payload = {
    karyawan_id: +(document.getElementById('payroll-karyawan').value || 0),
    bulan: +(bln || 0),
    tahun: +(thn || 0),
    gaji_pokok: +(document.getElementById('payroll-gaji').value || 0),
    tunjangan: +(document.getElementById('payroll-tunjangan').value || 0),
    potongan: +(document.getElementById('payroll-potongan').value || 0),
    status: document.getElementById('payroll-status').value,
  };
  if (!validateForm([{ id: 'payroll-karyawan', label: 'Karyawan', type: 'select' }])) return;
  const isEdit = !!id;
  if (isEdit) {
    api.put('/payroll/' + id, payload).then(() => loadPayroll());
  } else {
    api.post('/payroll', payload).then(() => loadPayroll());
  }
  document.getElementById('payroll-modal').classList.add('hidden');
  document.getElementById('payroll-modal').classList.remove('flex');
}

// ===== Tab Switch (harus global karena dipanggil dari template via onclick) =====
function switchPayTab(tab) {
  document.querySelectorAll('.tab-pay').forEach(b => b.classList.remove('active'));
  const el = document.getElementById('pay-tab-' + tab);
  if (el) el.classList.add('active');
  const bulanan = document.getElementById('pay-bulanan');
  const mingguan = document.getElementById('pay-mingguan');
  if (bulanan) bulanan.classList.toggle('hidden', tab !== 'bulanan');
  if (mingguan) mingguan.classList.toggle('hidden', tab !== 'mingguan');

  if (tab === 'mingguan') {
    const now = new Date();
    const blnSel = document.getElementById('pm-filter-bulan');
    if (blnSel) blnSel.value = now.getMonth() + 1;
    const thnInput = document.getElementById('pm-filter-tahun');
    if (thnInput) thnInput.value = now.getFullYear();
    loadPayrollMingguan();
  }
}

// ===== Payroll Mingguan =====
async function loadPayrollMingguan() {
  const bln = document.getElementById('pm-filter-bulan')?.value || '';
  const thn = document.getElementById('pm-filter-tahun')?.value || '';
  const mgg = document.getElementById('pm-filter-minggu')?.value || '1';
  if (!bln || !thn) return;
  try {
    const res = await api.get(`/payroll/mingguan?bulan=${bln}&tahun=${thn}&minggu_ke=${mgg}`);
    renderPayrollMingguanTable(res);
  } catch (e) {
    console.error('Payroll mingguan error:', e);
    const tb = document.getElementById('pm-tbody');
    if (tb) tb.innerHTML = `<tr><td colspan="12" class="text-center py-12 text-red-600">Gagal memuat: ${e.message}</td></tr>`;
  }
}

function renderPayrollMingguanTable(data) {
  const info = document.getElementById('pm-info');
  const label = document.getElementById('pm-label');
  const total = document.getElementById('pm-total');
  const thead = document.getElementById('pm-thead');
  const tbody = document.getElementById('pm-tbody');
  const tfoot = document.getElementById('pm-tfoot');
  const footHadir = document.getElementById('pm-foot-hadir');
  const footGaji = document.getElementById('pm-foot-gaji');

  if (!data || !data.karyawan || !data.minggu) {
    tbody.innerHTML = '<tr><td colspan="12" class="text-center py-12 text-stone-400">Tidak ada data</td></tr>';
    info.classList.add('hidden');
    tfoot.classList.add('hidden');
    return;
  }

  const { minggu, karyawan, totals } = data;

  // Info header
  info.classList.remove('hidden');
  label.innerHTML = '<svg class="w-3.5 h-3.5 inline -mt-0.5 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg> ' + minggu.label;
  total.textContent = `${totals.total_karyawan} karyawan · ${totals.total_hadir} hadir · Total: ${fmtIDR(totals.total_gaji)}`;

  // Day headers
  const daysHeader = document.getElementById('pm-header-days');
  daysHeader.textContent = `${minggu.dates.length} Hari Kerja`;

  const subHeader = document.getElementById('pm-header-sub');
  const tglNama = ['Min','Sen','Sel','Rab','Kam','Jum','Sab'];
  subHeader.innerHTML = minggu.dates.map((tgl, i) => {
    const d = new Date(tgl + 'T00:00:00');
    const hari = tglNama[d.getDay()];
    const tglNum = tgl.slice(8, 10);
    return `<th class="text-center px-1 py-1 text-[10px] font-semibold uppercase border-l border-stone-200 min-w-[72px] ${[0,6].includes(d.getDay()) ? 'text-red-400' : ''}">${hari}<br><span class="text-xs">${tglNum}</span></th>`;
  }).join('');

  // Body
  if (!karyawan.length) {
    tbody.innerHTML = '<tr><td colspan="12" class="text-center py-12 text-stone-400">Tidak ada karyawan aktif</td></tr>';
    tfoot.classList.add('hidden');
    return;
  }

  tfoot.classList.remove('hidden');
  footHadir.textContent = `${totals.total_hadir}`;
  footGaji.textContent = fmtIDR(totals.total_gaji);

  tbody.innerHTML = karyawan.map(k => `
    <tr class="border-t border-stone-100 hover:bg-stone-50">
      <td class="px-3 py-2 text-sm font-medium whitespace-nowrap">${k.nama}</td>
      <td class="px-2 py-2 text-xs text-stone-500 whitespace-nowrap border-r border-stone-200">${k.jabatan}</td>
      ${k.harian.map((h, i) => {
        const tgl = minggu.dates[i];
        const d = new Date(tgl + 'T00:00:00');
        const isWeekend = [0, 6].includes(d.getDay());
        if (!h) {
          return `<td class="text-center px-1 py-2 text-xs border-l border-stone-100 ${isWeekend ? 'bg-stone-50' : ''}">
            <span class="text-stone-300">—</span>
          </td>`;
        }
        if (h.status === 'Hadir') {
          return `<td class="text-center px-1 py-2 text-xs border-l border-stone-100 ${isWeekend ? 'bg-stone-50' : ''}">
            <div class="text-emerald-600 font-medium">${h.masuk || '?'}</div>
            <div class="text-stone-400">${h.keluar || '?'}</div>
          </td>`;
        }
        return `<td class="text-center px-1 py-2 text-xs border-l border-stone-100 ${isWeekend ? 'bg-stone-50' : ''}">
          <span class="text-${h.status === 'Sakit' ? 'amber' : h.status === 'Izin' ? 'blue' : h.status === 'Cuti' ? 'violet' : 'red'}-600">${h.status}</span>
        </td>`;
      }).join('')}
      <td class="text-center px-2 py-2 text-sm font-bold border-l border-stone-200">${k.total_hadir}x</td>
      <td class="text-right px-2 py-2 text-xs mono whitespace-nowrap">${fmtIDR(k.upah_per_hari)}</td>
      <td class="text-right px-2 py-2 text-sm font-bold mono whitespace-nowrap">${fmtIDR(k.total_gaji)}</td>
    </tr>
  `).join('');
}

// ===== Export Payroll Mingguan =====
async function exportPayrollMingguan() {
  const bln = document.getElementById('pm-filter-bulan')?.value || '';
  const thn = document.getElementById('pm-filter-tahun')?.value || '';
  const mgg = document.getElementById('pm-filter-minggu')?.value || '1';
  if (!bln || !thn) return showAlert('Pilih bulan & tahun terlebih dahulu', 'warning');

  try {
    const res = await api.get(`/payroll/mingguan?bulan=${bln}&tahun=${thn}&minggu_ke=${mgg}`);
    if (!res || !res.karyawan || !res.karyawan.length) {
      return showAlert('Tidak ada data untuk diexport', 'warning');
    }

    const { minggu, karyawan } = res;
    const days = minggu.dates;
    const tglNama = ['Min','Sen','Sel','Rab','Kam','Jum','Sab'];

    // Bangun headers dinamis: Nama | Jabatan | D1 Masuk | D1 Keluar | ... | Total Hadir | Upah/Hari | Total Gaji
    const headers = ['Nama Karyawan', 'Jabatan'];
    days.forEach((tgl, i) => {
      const d = new Date(tgl + 'T00:00:00');
      const label = tglNama[d.getDay()] + ' ' + tgl.slice(8,10) + '/' + tgl.slice(5,7);
      headers.push(label + ' Masuk', label + ' Keluar');
    });
    headers.push('Total Hadir', 'Upah/Hari', 'Total Gaji');

    // Data per karyawan
    const rows = karyawan.map(k => {
      const row = [k.nama, k.jabatan];
      k.harian.forEach(h => {
        if (h && h.status === 'Hadir') {
          row.push(h.masuk || '-', h.keluar || '-');
        } else if (h) {
          row.push(h.status, '-');
        } else {
          row.push('-', '-');
        }
      });
      row.push(k.total_hadir, k.upah_per_hari, k.total_gaji);
      return row;
    });

    // Baris total
    const totalHadir = karyawan.reduce((s, k) => s + k.total_hadir, 0);
    const totalGaji = karyawan.reduce((s, k) => s + k.total_gaji, 0);
    const totalRow = ['TOTAL', ''];
    days.forEach(() => { totalRow.push('', ''); });
    totalRow.push(totalHadir, '', totalGaji);
    rows.push(totalRow);

    // Buat workbook
    const wb = XLSX.utils.book_new();
    const wsData = [headers, ...rows];
    const ws = XLSX.utils.aoa_to_sheet(wsData);

    // Atur lebar kolom
    const colWidths = [
      { wch: 28 }, // Nama
      { wch: 18 }, // Jabatan
    ];
    days.forEach(() => { colWidths.push({ wch: 10 }, { wch: 10 }); });
    colWidths.push({ wch: 10 }, { wch: 12 }, { wch: 14 });
    ws['!cols'] = colWidths;

    XLSX.utils.book_append_sheet(wb, ws, 'Payroll Mingguan');

    const filename = `payroll-mingguan-${minggu.label.replace(/[\s,()]/g, '_')}.xlsx`;
    XLSX.writeFile(wb, filename);
  } catch (e) {
    console.error('Export mingguan error:', e);
    showAlert('Gagal export: ' + e.message, 'error');
  }
}

// ===== Bayar Payroll Mingguan =====
async function bayarPayrollMingguan() {
  const bln = document.getElementById('pm-filter-bulan')?.value || '';
  const thn = document.getElementById('pm-filter-tahun')?.value || '';
  const mgg = document.getElementById('pm-filter-minggu')?.value || '1';
  if (!bln || !thn) return showAlert('Pilih bulan & tahun terlebih dahulu', 'warning');

  if (!await showConfirm('Bayar payroll mingguan ini? Jurnal otomatis akan dibuat di Kas Bank.', 'Ya, Bayar')) return;

  try {
    const res = await api.post('/payroll/mingguan/bayar', { bulan: bln, tahun: thn, minggu_ke: parseInt(mgg) });
    if (res.ok) {
      showToast('✅ ' + res.pesan, 'success');
      loadPayrollMingguan(); // refresh
    }
  } catch (e) {
    if (e.status === 409) {
      showAlert('Jurnal untuk periode ini sudah ada di Kas Bank (No. ' + (e.data?.no_transaksi || '') + ')', 'warning');
    } else {
      showAlert('Gagal: ' + (e.message || ''), 'error');
    }
  }
}

// ===== Shift — Jadwal Kerja per Divisi =====

async function renderShift() {
  const c = document.getElementById('content');
  c.innerHTML = '<div class="flex items-center justify-center py-24"><svg class="animate-spin h-10 w-10 text-[#1e40af]" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24"><circle class="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" stroke-width="4"/><path class="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg></div>';
  try {
    const r = await fetch('/api/template/shift', { credentials: 'include' });
    if (!r.ok) { const err = await r.json(); throw new Error(err.error || 'Gagal memuat shift'); }
    c.innerHTML = await r.text();
    attachShiftHandlers();
    reloadJadwal();
  } catch (err) {
    console.error('Shift error:', err);
    if (err.message.includes('Akses ditolak') || err.message.includes('Forbidden')) return showAccessDenied();
    c.innerHTML = '<div class="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg">Gagal memuat shift: ' + err.message + '</div>';
  }
}

function attachShiftHandlers() {
  document.getElementById('add-shift-btn').onclick = function() { openShiftForm(null); };
  document.getElementById('add-jadwal-btn').onclick = function() { openJadwalForm(null); };
}

async function openShiftForm(editing) {
  var s = editing ? { ...editing, jam_masuk: (editing.jam_masuk || '').slice(0,5), jam_keluar: (editing.jam_keluar || '').slice(0,5) } : { nama: '', jam_masuk: '08:00', jam_keluar: '16:00', warna: '#3B82F6' };
  var divisiList = await api.get('/divisi');
  var selectedDivisi = [];
  if (editing) {
    var assigned = await api.get('/shift/' + editing.id + '/divisi');
    selectedDivisi = assigned.map(function(d) { return d.id; });
  }
  function selTime(id, val) { var h=val.slice(0,2), m=val.slice(3,5); return '<select id="'+id+'-h" class="w-20 h-10 px-2 rounded-lg border border-stone-200 text-sm mono focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all">'+Array.from({length:24},(_,i)=>'<option value="'+String(i).padStart(2,'0')+'" '+(h==String(i).padStart(2,'0')?'selected':'')+'>'+String(i).padStart(2,'0')+'</option>').join('')+'</select><span class="text-sm text-stone-400 mx-1">:</span><select id="'+id+'-m" class="w-20 h-10 px-2 rounded-lg border border-stone-200 text-sm mono focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all">'+['00','15','30','45'].map(function(v){return '<option value="'+v+'" '+(m==v?'selected':'')+'>'+v+'</option>'}).join('')+'</select>'; }
  function renderDivisiChecks() {
    if (!divisiList.length) return '<div class="text-xs text-stone-400 italic">Belum ada divisi. Buat divisi dulu di menu Divisi.</div>';
    return divisiList.map(function(d) {
      var checked = selectedDivisi.indexOf(d.id) !== -1 ? 'checked' : '';
      return '<label class="flex items-center gap-2 p-1.5 rounded hover:bg-stone-50 cursor-pointer"><input type="checkbox" class="sf-divisi-cb cb-modern" value="' + d.id + '" ' + checked + ' /><span class="text-sm">' + d.nama + '</span></label>';
    }).join('');
  }
  document.getElementById('modal-title').textContent = editing ? 'Edit Shift' : 'Shift Baru';
  document.getElementById('modal-body').innerHTML =
    '<div class="space-y-4">' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Nama Shift *</label><input id="sf-nama" value="' + s.nama + '" placeholder="cth: Shift Pagi" class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" /></div>' +
    '<div class="grid grid-cols-2 gap-3">' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Jam Masuk *</label><div class="mt-1.5 flex items-center">' + selTime('sf-masuk', s.jam_masuk) + '</div></div>' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Jam Keluar *</label><div class="mt-1.5 flex items-center">' + selTime('sf-keluar', s.jam_keluar) + '</div></div>' +
    '</div>' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Warna (opsional)</label><div class="flex items-center gap-2 mt-1.5"><input id="sf-warna" type="color" value="' + s.warna + '" class="h-10 w-14 rounded-lg border border-stone-200 cursor-pointer" /><span class="text-xs text-stone-500">' + s.warna + '</span></div></div>' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Digunakan oleh Divisi</label><div class="mt-1.5 border border-stone-200 rounded-xl p-2 max-h-40 overflow-y-auto space-y-0.5">' + renderDivisiChecks() + '</div></div>' +
    '</div>';

  document.getElementById('modal-save').onclick = async function() {
    var nama = document.getElementById('sf-nama').value.trim();
    var masuk = document.getElementById('sf-masuk-h').value + ':' + document.getElementById('sf-masuk-m').value;
    var keluar = document.getElementById('sf-keluar-h').value + ':' + document.getElementById('sf-keluar-m').value;
    var warna = document.getElementById('sf-warna').value;
    var divisi_ids = Array.from(document.querySelectorAll('.sf-divisi-cb:checked')).map(function(cb) { return +cb.value; });
    if (!nama) { showAlert('Nama shift harus diisi', 'warning'); return; }
    if (!masuk || !keluar) { showAlert('Jam masuk dan jam keluar harus diisi', 'warning'); return; }
    try {
      var payload = { nama: nama, jam_masuk: masuk, jam_keluar: keluar, warna: warna };
      var shift;
      if (editing) {
        await api.put('/shift/' + editing.id, payload);
        shift = editing;
      } else {
        shift = await api.post('/shift', payload);
      }
      if (divisiList.length) {
        await api.put('/shift/' + shift.id + '/divisi', { divisi_ids: divisi_ids });
      }
      closeModal(); renderShift();
    } catch (e) { showAlert('Gagal: ' + (e.message || 'Unknown error'), 'error'); }
  };
  document.getElementById('modal').classList.remove('hidden');
  document.getElementById('modal').classList.add('flex');
}

window.editShift = async function(id) {
  var list = await api.get('/shift');
  var s = list.find(function(x) { return x.id == id; });
  if (s) openShiftForm(s);
};

window.deleteShift = async function(id) {
  if (!await showConfirm('Hapus shift ini?')) return;
  await api.del('/shift/' + id);
  renderShift();
};

// ===== Jadwal Karyawan =====
var jadwalData = [];

async function reloadJadwal() {
  try {
    jadwalData = await api.get('/jadwal');
    renderJadwalTable(jadwalData);
  } catch (e) {
    var wrap = document.getElementById('jadwal-content');
    if (wrap) wrap.innerHTML = '<div class="text-center py-12 text-red-600">Gagal memuat jadwal</div>';
  }
}

function renderJadwalTable(list) {
  var wrap = document.getElementById('jadwal-content');
  if (!wrap) return;
  if (!list.length) {
    wrap.innerHTML = '<div class="text-center py-16 text-stone-400"><svg class="w-12 h-12 mx-auto mb-3 text-stone-300" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg><div class="text-sm">Belum ada jadwal shift.</div></div>';
    return;
  }
  var HARI = ['', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu', 'Minggu'];
  var rowsHtml = list.map(function(j) {
    var hariArr = (j.hari_kerja || '1,2,3,4,5,6,7').split(',').map(function(h) { return HARI[parseInt(h)] || ''; }).filter(Boolean);
    var hariLabel = hariArr.length >= 7 ? 'Setiap hari' : (hariArr.length === 5 && hariArr[0] === 'Senin' && hariArr[4] === 'Jumat' ? 'Sen-Jum' : hariArr.slice(0,3).join(',') + (hariArr.length > 3 ? '...' : ''));
    return '<tr class="border-b border-stone-50 hover:bg-stone-50/50 transition-colors">' +
      '<td class="px-4 py-3 text-xs font-medium text-stone-700">' + (j.nama_karyawan || '—') + '</td>' +
      '<td class="px-4 py-3 text-xs"><span class="inline-block px-2.5 py-0.5 rounded-lg text-[10px] font-semibold" style="background:' + (j.warna || '#3B82F6') + '20;color:' + (j.warna || '#3B82F6') + '">' + (j.shift_nama || '—') + '</span></td>' +
      '<td class="px-4 py-3 text-xs text-center mono text-stone-700">' + (j.jam_masuk ? j.jam_masuk.slice(0,5) : '—') + ' - ' + (j.jam_keluar ? j.jam_keluar.slice(0,5) : '—') + (j.jam_masuk && j.jam_keluar && j.jam_keluar <= j.jam_masuk ? '<span class="ml-1.5 text-[10px] font-semibold text-amber-600 bg-amber-50 px-1.5 py-0.5 rounded-lg cursor-default" title="Lintas hari (berakhir besok)">+1</span>' : '') + '</td>' +
      '<td class="px-4 py-3 text-xs text-center text-stone-600">' + (j.tanggal_mulai || '—') + '</td>' +
      '<td class="px-4 py-3 text-xs text-center text-stone-600">' + (j.tanggal_selesai || '—') + '</td>' +
      '<td class="px-4 py-3 text-xs text-center text-stone-600">' + hariLabel + '</td>' +
      '<td class="px-4 py-3 text-xs text-right whitespace-nowrap"><button onclick="editJadwal(' + j.id + ')" class="w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-blue-600 hover:bg-blue-50 transition-all" title="Edit"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"/><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"/></svg></button><button onclick="deleteJadwal(' + j.id + ')" class="w-7 h-7 inline-flex items-center justify-center rounded-lg text-stone-400 hover:text-red-600 hover:bg-red-50 transition-all" title="Hapus"><svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button></td></tr>';
  }).join('');
  wrap.innerHTML = '<div class="overflow-x-auto"><table class="w-full"><thead><tr class="border-b border-stone-100">' +
    '<th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Karyawan</th>' +
    '<th class="text-left px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Shift</th>' +
    '<th class="text-center px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Jam</th>' +
    '<th class="text-center px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Mulai</th>' +
    '<th class="text-center px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Selesai</th>' +
    '<th class="text-center px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Hari</th>' +
    '<th class="text-right px-4 py-3.5 text-[10px] font-bold uppercase tracking-wider text-stone-500">Aksi</th></tr></thead><tbody>' +
    rowsHtml + '</tbody></table></div>';
}

async function openJadwalForm(editing) {
  var shiftList = await api.get('/shift');
  var karyawanList = await api.get('/karyawan?status=Aktif');
  var j = editing || { karyawan_id: '', shift_id: '', tanggal_mulai: new Date().toISOString().slice(0,10), tanggal_selesai: '', hari_kerja: '1,2,3,4,5,6,7' };
  document.getElementById('modal-title').textContent = editing ? 'Edit Jadwal Shift' : 'Atur Jadwal Shift';
  document.getElementById('modal-body').innerHTML =
    '<div class="space-y-4">' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Karyawan *</label><select id="jd-karyawan" class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all"><option value="">— Pilih Karyawan —</option>' +
    karyawanList.map(function(k) { return '<option value="' + k.id + '" ' + (j.karyawan_id == k.id ? 'selected' : '') + '>' + k.nama + ' — ' + (k.jabatan_nama || '-') + '</option>'; }).join('') +
    '</select></div>' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Shift *</label><select id="jd-shift" class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all"><option value="">— Pilih Shift —</option>' +
    shiftList.map(function(s) { return '<option value="' + s.id + '" ' + (j.shift_id == s.id ? 'selected' : '') + '>' + s.nama + ' (' + s.jam_masuk.slice(0,5) + '-' + s.jam_keluar.slice(0,5) + ')</option>'; }).join('') +
    '</select></div>' +
    '<div class="grid grid-cols-2 gap-3">' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Tanggal Mulai *</label><input id="jd-mulai" type="date" value="' + j.tanggal_mulai + '" class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" /></div>' +
    '<div><label class="text-xs font-semibold text-stone-600 uppercase tracking-wider">Tanggal Selesai</label><input id="jd-selesai" type="date" value="' + (j.tanggal_selesai || '') + '" class="mt-1.5 w-full h-11 px-3 rounded-lg border border-stone-200 text-sm focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all" /><div class="text-[10px] text-stone-400 mt-1">Kosongkan jika tidak ada batas</div></div>' +
    '</div></div>';

  document.getElementById('modal-save').onclick = async function() {
    var karyawan_id = document.getElementById('jd-karyawan').value;
    var shift_id = document.getElementById('jd-shift').value;
    var mulai = document.getElementById('jd-mulai').value;
    var selesai = document.getElementById('jd-selesai').value;
    if (!karyawan_id) { showAlert('Pilih karyawan', 'warning'); return; }
    if (!shift_id) { showAlert('Pilih shift', 'warning'); return; }
    if (!mulai) { showAlert('Tanggal mulai harus diisi', 'warning'); return; }
    try {
      var payload = { karyawan_id: +karyawan_id, shift_id: +shift_id, tanggal_mulai: mulai, tanggal_selesai: selesai || null, hari_kerja: '1,2,3,4,5,6,7' };
      if (editing) await api.put('/jadwal/' + editing.id, payload);
      else await api.post('/jadwal', payload);
      closeModal(); renderShift();
    } catch (e) { showAlert('Gagal: ' + (e.message || 'Unknown error'), 'error'); }
  };
  document.getElementById('modal').classList.remove('hidden');
  document.getElementById('modal').classList.add('flex');
}

window.editJadwal = async function(id) {
  try {
    var j = await api.get('/jadwal/' + id);
    if (j) openJadwalForm(j);
  } catch(e) { showAlert('Gagal memuat jadwal', 'error'); }
};

window.deleteJadwal = async function(id) {
  if (!await showConfirm('Hapus jadwal ini?')) return;
  await api.del('/jadwal/' + id);
  reloadJadwal();
};

