  budgeting: { title: 'Budgeting', sub: 'Anggaran per periode & kategori', icon: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" ry="2"/><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/></svg>',
    crud: { endpoint: '/budget', formHelp: 'Untuk biaya <strong>non-PM</strong> (gas, listrik, transport): kosongkan Jml Penerima & Harga Porsi (isi 0), lalu isi Biaya Operasional saja. Kategori bisa "Operasional Dapur".', fields: [
      { k: 'periode', l: 'Periode', req: true, info: 'Bulan & tahun anggaran, contoh: 2026-07' },
      { k: 'kategori_penerima', l: 'Kategori', info: 'Jenis penerima manfaat (Balita, Bumil, Lansia, dll)' },
      { k: 'jumlah_penerima', l: 'Jml Penerima', type: 'number', fmt: 'num', info: 'Total penerima manfaat untuk kategori ini' },
      { k: 'harga_besar', l: 'Harga Porsi Besar (IDR)', type: 'number', fmt: 'idr', info: 'Biaya bahan pangan per porsi untuk kategori besar (Balita)' },
      { k: 'harga_kecil', l: 'Harga Porsi Kecil (IDR)', type: 'number', fmt: 'idr', info: 'Biaya bahan pangan per porsi untuk kategori kecil (Bumil/Busui)' },
      { k: 'biaya_operasional', l: 'Biaya Operasional (IDR)', type: 'number', fmt: 'idr', info: 'Biaya tambahan: gas, listrik, transport, dll' },
      { k: 'total_budget', l: 'Total Budget (IDR)', type: 'number', fmt: 'idr', req: true, info: '(Jml Penerima × Harga Porsi) + Biaya Operasional' },
      { k: 'realisasi', l: 'Realisasi (IDR)', type: 'number', fmt: 'idr', info: 'Terisi otomatis dari transaksi kas' },
    ], cols: ['periode','kategori_penerima','jumlah_penerima','harga_besar','harga_kecil','biaya_operasional','total_budget','realisasi'] },
    extraButtons: [
      { label: 'Hitung Ulang Realisasi', onclick: 'recalculateRealisasi()', cls: 'border border-blue-400 text-blue-700 hover:bg-blue-50 px-4 py-2 rounded-md text-sm font-medium' },
      { label: 'Backfill Jurnal', onclick: 'backfillJournal()', cls: 'border border-amber-400 text-amber-700 hover:bg-amber-50 px-4 py-2 rounded-md text-sm font-medium' },
    ],
    helpContent: [
      { title: 'Apa itu Budgeting?', text: 'Budgeting (Anggaran) adalah rencana keuangan per periode untuk biaya program MBG. Mencakup biaya bahan pangan (dari harga per porsi x jumlah penerima) dan biaya operasional dapur.' },
      { title: 'Cara Mengisi', text: 'Klik <strong>Tambah</strong> untuk membuat entri baru per periode. Isi periode (YYYY-MM), kategori penerima, jumlah penerima, harga porsi besar, harga porsi kecil, dan biaya operasional. Total budget akan terhitung otomatis.' },
      { title: 'Realisasi & Laporan', text: 'Gunakan tombol <strong>Hitung Ulang Realisasi</strong> untuk update realisasi dari transaksi kas bank yang sudah tercatat. Cek laporan <strong>RAB</strong> untuk perbandingan budget vs realisasi per periode.' },
    ],
  },
  'daftar-akun': { title: 'Daftar Akun', sub: 'Kode Akun & Buku Pembantu (COA)', icon: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="3" width="20" height="14" rx="2" ry="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>',
    crud: { endpoint: '/akun', fields: [
      { k: 'kode', l: 'Kode Akun', req: true },
      { k: 'nama', l: 'Nama Akun', req: true },
      { k: 'bp', l: 'Buku Pembantu', type: 'select', opts: ['BP Kas','BP Jenis Dana','BP Operasional'], req: true },
      { k: 'tipe', l: 'Tipe', type: 'select', opts: ['Manual','Otomatis'] },
      { k: 'is_active', l: 'Aktif', type: 'select', opts: ['1','0'] },
    ], cols: ['kode','nama','bp','tipe','is_active'] }
  },
  'bp-operasional': { title: 'Buku Pembantu Operasional', sub: 'Laporan detail transaksi operasional per akun', icon: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg>', render: renderBpOperasional },
  'kas-bank': { title: 'Kas & Bank', sub: 'Penerimaan dana, pembayaran supplier & biaya operasional', icon: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>',
    crud: { endpoint: '/kas_bank', formHelp: '<strong>Masuk</strong> = penerimaan dana (donasi, BP). <strong>Keluar</strong> = pembayaran (supplier, gaji, operasional). Transaksi <strong>keluar</strong> otomatis mengurangi realisasi budget di RAB berdasarkan kategori.', fields: [
      { k: 'tanggal', l: 'Tanggal', type: 'date', req: true, info: 'Tanggal transaksi terjadi' },
      { k: 'no_transaksi', l: 'No Transaksi', info: 'Nomor referensi: INV-xxx, BPK-xxxx, dll' },
      { k: 'tipe', l: 'Tipe', type: 'select', opts: ['masuk','keluar'], req: true, info: 'Masuk = uang masuk, Keluar = uang keluar' },
      { k: 'kategori', l: 'Kategori', type: 'select', opts: ['Penerimaan Dana','Pembayaran Supplier','Biaya Operasional','Gaji','Lainnya'], info: 'Menentukan mapping jurnal & realisasi budget' },
      { k: 'akun_id', l: 'Akun (BP Kas)', type: 'select-api', source: '/akun?bp=BP Kas', valueField: 'id', labelField: 'nama', info: 'Pilih akun kas atau bank yang sesuai' },
      { k: 'deskripsi', l: 'Deskripsi', type: 'textarea', info: 'Detail transaksi: untuk apa, kepada siapa' },
      { k: 'jumlah', l: 'Jumlah (IDR)', type: 'number', fmt: 'idr', req: true, info: 'Nominal transaksi dalam Rupiah' },
    ], cols: ['tanggal','no_transaksi','tipe','kategori','akun','jumlah'] }
  },
  'laporan-rab': { title: 'RAB', sub: 'Laporan anggaran vs realisasi', icon: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="12" width="4" height="8"/><rect x="10" y="4" width="4" height="16"/><rect x="17" y="8" width="4" height="12"/><path d="M3 2v20M21 2v20"/></svg>', render: renderLapRab },
'laporan-rab-bulanan': { title: 'RAB Bulanan', sub: 'Aggregasi budget per bulan', icon: '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/><polyline points="8 14 12 14 12 18"/><line x1="6" y1="18" x2="18" y2="18"/></svg>', render: renderLapRabBulanan },
